func (s *Service) saveDerivation(ctx context.Context, v *v1.ContentDerivation) error {
	if err := s.store.(derivationStore).SaveContentDerivation(ctx, v); err != nil {
		return err
	}
	refs := []*v1.Ref{v.OutputRef, v.LocationRef, v.PreviousVersionRef}
	refs = append(refs, v.ActualInputRefs...)
	refs = append(refs, v.SealedInputRefs...)
	return s.store.SaveTraceSource(ctx, "content", &v1.TraceEvent{EventType: "DERIVATION_" + v.State, SourceRecordRef: v.Ref, TaskId: v.TaskId, OperationId: v.OperationId, AttemptId: v.AttemptId, OriginCommand: v.Responsibility, RelatedRefs: refs})
}

func (s *Store) CreateTraceSource(ctx context.Context, producer string, event *v1.TraceEvent, header *v1.CommandHeader) (*v1.AcceptTraceCommand, error) {
	domain := traceSourceDomain(producer)
	if domain == "" {
		return nil, command.Fail("INVALID_TRACE_SOURCE")
	}
	tx, err := s.writer(ctx, domain)
	if err != nil {
		return nil, err
	}
	event = proto.Clone(event).(*v1.TraceEvent)
	event.Producer = producer
	event.SourceStreamId = s.domain + "/" + producer
	event.MappingVersion = "lerna.m1.local.v1"
	event.SourceSchemaVersion = 1
	event.ProducerVersion = "lerna-m1-source-v1"
	if event.Ref == nil {
		event.Ref = command.NewRef(s.user, s.domain+"/trace", "trace-event", "lerna.v1.TraceEvent")
	}
	refs := make([]*v1.Ref, 0, len(event.RelatedRefs))
	for _, ref := range event.RelatedRefs {
		if ref != nil && ref.Name != nil {
			refs = append(refs, ref)
		}
	}
	event.RelatedRefs = refs
	if err = tx.QueryRowContext(ctx, "INSERT INTO source_trace_streams VALUES(?,?,1) ON CONFLICT(user_id,producer) DO UPDATE SET seq=seq+1 RETURNING seq", s.user, producer).Scan(&event.SourceSeq); err != nil {
		return nil, storageError(err, false)
	}
	if header == nil {
		header = &v1.CommandHeader{Identity: &v1.CommandIdentity{UserId: s.user, IssuerId: "trace-source/" + producer, TargetDomainId: s.domain + "/trace", CommandId: event.Ref.Name.LocalId}, ContractVersion: 1, FingerprintVersion: 1, SchemaId: "lerna.v1.AdmissionCommands"}
	}
	c := &v1.AcceptTraceCommand{Header: header, Event: event}
	source := &v1.TraceSourceRecord{Command: c}
	err = s.saveRecord(ctx, domain, "INSERT INTO source_trace_outbox VALUES(?,?,?,?,?,?,?,?)", source, s.user, producer, event.SourceSeq, header.Identity.IssuerId, header.Identity.TargetDomainId, header.Identity.CommandId, command.SemanticFingerprint("accept-trace", event))
	return c, err

func (s *Service) Accept(ctx context.Context, caller *v1.Caller, c *v1.AcceptTraceCommand) (*v1.CommandReceipt, error) {
	if e := command.ValidateHeader(c.GetHeader(), c); e != nil {
		return nil, e
	}
	if caller.GetIssuerId() != "ledger-report" && !strings.HasPrefix(caller.GetIssuerId(), "trace-source/") {
		return nil, command.Fail("PERMISSION_DENIED")
	}
	return s.work.Execute(ctx, caller, c.Header, command.SemanticFingerprint("accept-trace", c.Event), "trace.accept", func(tx context.Context) (*v1.Ref, error) {
		ev := c.Event
		if ev.GetProducer() != "" {
			if ev == nil || ev.Ref == nil || ev.Ref.Name == nil || ev.Ref.Name.UserId != s.user || ev.Ref.Name.AuthorityDomainId != s.domain || ev.SourceRecordRef == nil || ev.SourceSeq == 0 {
				return nil, command.Fail("INVALID_TRACE_EVENT")
			}
			source, err := s.store.(Sources).LoadTraceSource(tx, c.Header.Identity)
			if err != nil {
				return nil, err
			}
			if source == nil || !proto.Equal(source.Command, c) {
				return nil, command.Fail("INVALID_TRACE_SOURCE")
			}
			return ev.Ref, s.store.SaveTraceEvent(tx, ev)
		}
		if ev == nil || ev.Ref == nil || ev.Ref.Name == nil || ev.Ref.Name.UserId != s.user || ev.Ref.Name.AuthorityDomainId != s.domain || ev.EventType != "PHYSICAL_OBSERVATION" || ev.ObservationRef == nil || ev.BodyRef == nil {
			return nil, command.Fail("INVALID_TRACE_EVENT")
		}
		source, e := s.source.QueryReports(tx, caller, ev.ObservationRef)
		if e != nil {
			return nil, e
		}
		if source == nil || !proto.Equal(source.Trace, c) {
			return nil, command.Fail("INVALID_TRACE_SOURCE")
		}
		return ev.Ref, s.store.SaveTraceEvent(tx, ev)
	})

