				w.WriteHeader(status)
				account, origin, key := r.Header.Get("Lerna-Account"), "http://"+r.Host, r.Header.Get("Idempotency-Key")
				switch kind {
				case "wrong-account":
					account = "other"
				case "wrong-origin":
					origin = "https://other.invalid"
				case "wrong-key":
					key = "other"
				}
