		t.Fatalf("missing content admitted: %v %v", r, e)
	}
	current, e := f.h.Sessions.QueryCurrentConfirmation(f.ctx, f.caller, pending.Ref.Name)
	if e != nil || current.State != "APPROVED" || !proto.Equal(current.Ref, approved) {
