		t.Fatal(e)
	}
	f.h, e = assembly.Open(f.path, "u", "d")
	if e != nil {
		t.Fatal(e)
	}
	again, e := f.h.Tasks.RunModelCall(f.ctx, f.caller, run)
	if e != nil || !proto.Equal(original, again) || provider.Calls() != 1 {
		t.Fatalf("unknown replay: %v %v", again, e)
