	f := newFixture(t, 100, 80, false)
	r, e := f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("admit"), TaskId: f.task.Name, ProposalRef: f.propose(t, nil), GrantRef: f.grant})
