	c := &v1.SubmitInputCommand{Header: header("answer"), SessionId: id, TaskId: task.TaskId, InputKind: "ANSWER", ContentRef: stage(t, h, "answer-text", "yes"), ExpectedInputVersion: 1, ExpectedRequirementsVersion: 1, RequestRef: q}
