func TestStorageNegativeControls(t *testing.T) {
	for _, mode := range []string{"NORMAL", "OFF", "omit-sync"} {
		t.Run(mode, func(t *testing.T) {
			events, acks, base := storageRun(t, mode)
			path := storageImage(t, base, events, "lost")
