func TestTraceOutOfOrderKeepsGapsAndRejectsForgedCoreProducer(t *testing.T) {
	f := newFixture(t, 100, 80, false)
	sources, err := f.h.Trace.QuerySources(f.ctx, f.caller)
	if err != nil {
