func TestAPICrashRecoveryPreservesWaitAndSingleRequest(t *testing.T) {
	for _, point := range []string{"tasks.start", "ledger.dispatch", "content.observation", "body.accept", "content.publish", "ledger.observation", "content.observation_ack", "budget.usage", "trace.accept", "ledger.usage_ack", "ledger.trace_ack", "ledger.interpret", "trace.source_ack", "trace.index"} {
		for _, mode := range []sqlite.FaultMode{sqlite.CrashBeforeCommit, sqlite.CrashAfterCommit, sqlite.LoseReceipt} {
			t.Run(point+"/"+string(mode), func(t *testing.T) {
				var calls atomic.Int64
				target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					calls.Add(1)
					w.Header().Set("Lerna-Rate-Category", "CONCURRENCY")
					w.Header().Set("Retry-After", "30")
					w.WriteHeader(429)
					_ = json.NewEncoder(w).Encode(map[string]any{"protocol": "lerna-reference-api-v1", "external_key": r.Header.Get("Idempotency-Key"), "attempt_id": r.Header.Get("Lerna-Attempt"), "account": r.Header.Get("Lerna-Account"), "origin": "http://" + r.Host, "applied": false, "terminal": true})
				}))
				defer target.Close()
				path := filepath.Join(t.TempDir(), "state.db")
				h, keychain, a, start := prepareAPIStartFault(t, path, target.URL)
				writeStart(t, path, start)
				if e := h.Close(); e != nil {
					t.Fatal(e)
				}
				child := exec.Command(os.Args[0], "-test.run=^TestAPICrashChild$")
				child.Env = append(os.Environ(), "LERNA_API_FAULT_DB="+path, "LERNA_API_FAULT_POINT="+point, "LERNA_API_FAULT_MODE="+string(mode), "LERNA_API_FAULT_KEYCHAIN="+keychain.Path())
				out, e := child.CombinedOutput()
				if mode == sqlite.LoseReceipt {
					if e != nil {
						t.Fatalf("child%v %s", e, out)
					}
				} else {
					var exit *exec.ExitError
					if !errors.As(e, &exit) || exit.ExitCode() != sqlite.CrashExitCode {
						t.Fatalf("no crash%v %s", e, out)
					}
				}
				h, e = assembly.OpenWithOptions(path, "u", "d", assembly.Options{APIKeychainPath: keychain.Path()})
				if e != nil {
					t.Fatal(e)
				}
				defer h.Close()
				ctx, actor := context.Background(), &v1.Caller{UserId: "u", IssuerId: "egress"}
				r, e := h.Egress.Invoke(ctx, actor, start)
				requireAccepted(t, r, e)
				op, e := h.Ledger.QueryOperation(ctx, actor, a.OperationId)
				if e != nil || op.Effect.Outcome != "UNKNOWN" || op.Effect.LateEffect != "MAY_OCCUR" {
					t.Fatalf("lost uncertainty%v %v", op, e)
				}
				expectedCalls := int64(1)
				lostRaw := point == "content.observation" && mode == sqlite.CrashBeforeCommit
				if point == "ledger.dispatch" && mode != sqlite.CrashBeforeCommit {
					expectedCalls = 0
					lostRaw = true
				}
				if calls.Load() != expectedCalls {
					t.Fatalf("calls%d expected%d", calls.Load(), expectedCalls)
				}
				if lostRaw {
					if op.ApiWait != nil || len(op.Effect.EvidenceRefs) != 0 {
						t.Fatal("invented missing observation")
					}
				} else {
					raw, e := h.Ledger.QueryObservation(ctx, actor, op.Execution.Send.ObservationRef)
					if e != nil || op.ApiWait == nil || op.ApiWait.Category != "CONCURRENCY" || op.ApiWait.ReadyAtUnixMs != raw.FinishedAtUnixMs+30000 || !proto.Equal(op.ApiWait.ObservationRef, raw.Ref) || len(op.Effect.EvidenceRefs) != 1 {
						t.Fatalf("lost original wait%v %v", op.ApiWait, e)
					}
					before := proto.Clone(op)
					r, e = h.Egress.Invoke(ctx, actor, start)
					requireAccepted(t, r, e)
					replay, e := h.Ledger.QueryOperation(ctx, actor, a.OperationId)
					if e != nil || !proto.Equal(replay, before) || calls.Load() != expectedCalls {
						t.Fatal("wait replay changed records or target")
					}
				}
				budget, e := h.Budget.QueryBudget(ctx, actor, a.TaskId)
				if e != nil || budget.Reserved != 30 {
					t.Fatalf("lost original fee%v %v", budget, e)
				}
				wantWaits := 1
				if lostRaw {
					wantWaits = 0
				}
				assertAPIRecoveredSources(t, h, op, wantWaits, keychain.Path(), target.URL, "synthetic-api-fault-secret-f17e4038")
			})
		}
	}
}

func TestAPICredentialEchoCannotBecomeContentTraceOrEvidence(t *testing.T) {
	for _, where := range []string{"body", "base64", "hex", "request-id", "rate-category", "retry-after", "escaped-json", "partial-body", "oversized-body"} {
		t.Run(where, func(t *testing.T) {
			secret := []byte("synthetic-native-echo-canary-a6aebd19")
			target := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				switch where {
				case "body":
					_, _ = w.Write(secret)
				case "base64":
					_, _ = w.Write([]byte(base64.StdEncoding.EncodeToString(secret)))
				case "hex":
					_, _ = w.Write([]byte(hex.EncodeToString(secret)))
				case "oversized-body":
					_, _ = w.Write(append(append([]byte(nil), secret...), bytes.Repeat([]byte("x"), 1<<20)...))
				case "request-id":
					w.Header().Set("X-Request-ID", string(secret))
					_, _ = w.Write([]byte(`{"safe":true}`))
				case "rate-category":
					w.Header().Set("Lerna-Rate-Category", string(secret))
					w.WriteHeader(429)
				case "retry-after":
					w.Header().Set("Retry-After", string(secret))
					w.WriteHeader(429)
				case "escaped-json":
					_, _ = fmt.Fprintf(w, `{"echo":"\u0073%s"}`, secret[1:])
				case "partial-body":
					w.Header().Set("Content-Length", "1000")
					_, _ = w.Write(secret)
				}
			})
			f := newFixtureWithTarget(t, 100, 80, false, target)
			d := configureAPI(t, f)
			withAPIKeychain(t, f, d, secret)
			a, c := prepareStart(t, f)
			r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, c)
			accepted(t, r, e)
			op, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if e != nil {
				t.Fatal(e)
			}
			raw, e := f.h.Ledger.QueryObservation(f.ctx, f.caller, op.Execution.Send.ObservationRef)
			if e != nil {
				t.Fatal(e)
			}
			body, e := f.h.Content.Read(f.ctx, f.caller, raw.BodyRef)
			if e != nil {
				t.Fatal(e)
			}
			reports, e := f.h.Ledger.QueryReports(f.ctx, f.caller, raw.Ref)
			if e != nil {
				t.Fatal(e)
			}
			if !raw.Redacted || raw.TransportError != "CREDENTIAL_ECHO_REDACTED" || len(body.RawBody) != 0 || body.Text != "" || op.Effect.Outcome != "UNKNOWN" || bytes.Contains([]byte(raw.String()+body.String()+reports.String()+op.String()), secret) || f.calls.Load() != 1 {
				t.Fatalf("unsafe echo escaped %s", where)
			}
			for _, path := range []string{f.path, f.path + "-wal", f.path + "-journal"} {
				data, e := os.ReadFile(path)
				if e == nil && bytes.Contains(data, secret) {
					t.Fatal("credential was persisted in state artifact")
				}
			}
			if e = f.h.Trace.Recover(f.ctx, f.caller); e != nil {
				t.Fatal(e)
			}
			assertAPITraceExcludes(t, f, string(secret), base64.StdEncoding.EncodeToString(secret), hex.EncodeToString(secret), d.Binding.Origin)
		})
	}
}

func TestAPICredentialRotationUsesCurrentNativeSecretWithFixedIdentity(t *testing.T) {
	oldSecret, newSecret := []byte("synthetic-rotation-first-canary-c8392140"), []byte("synthetic-rotation-second-canary-a5423eb6")
	var calls atomic.Int64
	var valid atomic.Bool
	target := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := calls.Add(1)
		expected := oldSecret
		if n == 2 {
			expected = newSecret
		}
		if r.Header.Get("Authorization") != "Bearer "+string(expected) {
			valid.Store(false)
		}
		if n == 1 {
			w.Header().Set("Retry-After", "0")
			w.Header().Set("Lerna-Rate-Category", "RATE")
			w.WriteHeader(429)
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"protocol": "lerna-reference-api-v1", "external_key": r.Header.Get("Idempotency-Key"), "attempt_id": r.Header.Get("Lerna-Attempt"), "account": r.Header.Get("Lerna-Account"), "origin": "http://" + r.Host, "applied": true, "terminal": true})
	})
	valid.Store(true)
	f := newFixtureWithTarget(t, 100, 80, false, target)
	d := configureAPI(t, f)
	configureResendLimit(t, f, 2)
	keychain := withAPIKeychain(t, f, d, oldSecret)
	a, first := prepareStart(t, f)
	r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, first)
	accepted(t, r, e)
	before, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil {
		t.Fatal(e)
	}
	if e = keychain.Put(d.Binding, newSecret); e != nil {
		t.Fatal(e)
	}
	time.Sleep(max(0, time.Until(time.UnixMilli(before.ApiWait.ReadyAtUnixMs))) + 20*time.Millisecond)
	second := prepareNextResend(t, f, a, first)
	r, e = f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, second)
	accepted(t, r, e)
	after, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil || !valid.Load() || calls.Load() != 2 || !proto.Equal(before.Execution.CallDescriptor, after.Execution.CallDescriptor) || !proto.Equal(before.Execution.Attempt.Ref.Name, after.Execution.Attempt.Ref.Name) || before.Execution.Attempt.ExternalKey != after.Execution.Attempt.ExternalKey || after.Effect.Outcome != "APPLIED" {
		t.Fatal("native rotation changed fixed attempt or used stale secret")
	}
	if bytes.Contains([]byte(after.String()), oldSecret) || bytes.Contains([]byte(after.String()), newSecret) {
		t.Fatal("rotation leaked secret to records")
	}
}

