					_, _ = fmt.Fprintf(w, `{"protocol":"lerna-reference-api-v1","external_key":%q,"attempt_id":%q,"account":%q,"origin":%q,"applied":true,"applied":false,"terminal":true}`, key, r.Header.Get("Lerna-Attempt"), account, origin)
