			})
			f := newFixtureWithTarget(t, 100, 80, false, target)
			d := configureAPI(t, f)
			withAPIKeychain(t, f, d, []byte("synthetic-terminal-canary-6ecbb89b"))
			a, c := prepareStart(t, f)
			r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, c)
			accepted(t, r, e)
			op, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if e != nil {
				t.Fatal(e)
			}
			outcome, late, lifecycle := "UNKNOWN", "MAY_OCCUR", "ACTIVE"
			assertFixedExecutionDeclaration(t, op.Execution.Attempt.Capabilities, "lerna-reference-api-v1", "reference-api-v1")
			assertOriginalProofRule(t, f, op, "reference-api-v1")
			switch kind {
			case "applied":
				outcome, late, lifecycle = "APPLIED", "RULED_OUT", "SETTLED"
			case "not-applied":
				outcome, late, lifecycle = "NOT_APPLIED", "RULED_OUT", "SETTLED"
			}
			if op.Effect.Outcome != outcome || op.Effect.LateEffect != late || op.Lifecycle != lifecycle || f.calls.Load() != 1 {
				t.Fatalf("%s: effect %v lifecycle %s sends%d", kind, op.Effect, op.Lifecycle, f.calls.Load())
			}
		})
	}
}

func TestAPIOriginalAttemptQueryPreservesWeakEvidenceAndRestoresLateEffect(t *testing.T) {
	var visible atomic.Bool
	var writes, queries, effects atomic.Int64
	var queryIdentityMu sync.Mutex
	var subjects []string
	target := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == "POST" {
			writes.Add(1)
			effects.Add(1)
			conn, _, e := w.(http.Hijacker).Hijack()
			if e != nil {
				t.Error(e)
				return
			}
			_ = conn.Close()
			return
		}
		if r.Method != "GET" {
			t.Error("unexpected request method")
			w.WriteHeader(405)
			return
		}
		queries.Add(1)
		body, e := io.ReadAll(r.Body)
		if e != nil || len(body) != 0 {
			t.Error("query sent a business payload")
		}
		queryIdentityMu.Lock()
		subjects = append(subjects, r.Header.Get("Lerna-Query-Operation")+"/"+r.Header.Get("Lerna-Query-Attempt")+"/"+r.Header.Get("Lerna-Query-Key")+"/"+r.Header.Get("Lerna-Query-Scope"))
		queryIdentityMu.Unlock()
		applied := visible.Load()
		_ = json.NewEncoder(w).Encode(map[string]any{"protocol": "lerna-reference-api-query-v1", "account": r.Header.Get("Lerna-Account"), "origin": "http://" + r.Host, "query_status": "AVAILABLE", "query_external_key": r.Header.Get("Idempotency-Key"), "query_attempt_id": r.Header.Get("Lerna-Attempt"), "query_operation_id": r.Header.Get("Lerna-Operation"), "read_terminal": true, "subject_external_key": r.Header.Get("Lerna-Query-Key"), "subject_attempt_id": r.Header.Get("Lerna-Query-Attempt"), "subject_operation_id": r.Header.Get("Lerna-Query-Operation"), "subject_scope": r.Header.Get("Lerna-Query-Scope"), "applied": applied, "terminal": applied, "negative_proof": false, "retry_after_ms": 1000})
	})
	f := newFixtureWithTarget(t, 200, 200, false, target)
	d, queryCap, queryGrant := configureAPIQueryable(t, f, false)
	keychain := withAPIKeychain(t, f, d, []byte("synthetic-query-native-canary-03f8e024"))
	scopeRequirement(t, f)
	a, start := prepareStart(t, f)
	r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
	accepted(t, r, e)
	before, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil || before.Effect.Outcome != "UNKNOWN" {
		t.Fatalf("lost receipt %v %v", before, e)
	}
	r, e = f.h.Ledger.RequestReconciliation(f.ctx, f.caller, reconciliationCommand(f, a, queryCap, queryGrant))
	accepted(t, r, e)
	if e = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	plan, e := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || plan.State != "WAITING" || plan.CheckCount != 1 {
		t.Fatalf("weak query schedule %v %v", plan, e)
	}
	relation, e := f.h.Ledger.QueryReconciliationQuery(f.ctx, f.caller, plan.QueryRefs[0])
	if e != nil {
		t.Fatal(e)
	}
	queryOperation, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, relation.QueryOperationRef.Name)
	if e != nil {
		t.Fatal(e)
	}
	assertFixedExecutionDeclaration(t, queryOperation.Execution.Attempt.Capabilities, "lerna-reference-api-query-v1", "reference-api-v1")
	assertOriginalProofRule(t, f, queryOperation, "reference-api-query-v1")
	subjectFinding, e := f.h.Ledger.QueryReconciliationFinding(f.ctx, f.caller, relation.InterpretationRef)
	if e != nil || subjectFinding.Rule != "reference-api-query-subject-v1" || subjectFinding.Outcome != "UNKNOWN" || subjectFinding.LateEffect != "MAY_OCCUR" || queryOperation.Effect.Outcome != "APPLIED" || queryOperation.Effect.LateEffect != "RULED_OUT" {
		t.Fatalf("terminal API read became original subject proof: %v %v", subjectFinding, e)
	}
	original, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil || original.Effect.Outcome != "UNKNOWN" || original.Effect.LateEffect != "MAY_OCCUR" || writes.Load() != 1 || queries.Load() != 1 || effects.Load() != 1 {
		t.Fatalf("weak absence changed original effect%v %v", original, e)
	}
	if e = f.h.Close(); e != nil {
		t.Fatal(e)
	}
	f.h, e = assembly.OpenWithOptions(f.path, "u", "d", assembly.Options{APIKeychainPath: keychain.Path()})
	if e != nil {
		t.Fatal(e)
	}
	restored, e := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || restored.NextReconcileAtUnixMs != plan.NextReconcileAtUnixMs || queries.Load() != 1 {
		t.Fatalf("query restoration %v %v", restored, e)
	}
	visible.Store(true)
	time.Sleep(max(0, time.Until(time.UnixMilli(plan.NextReconcileAtUnixMs))) + 20*time.Millisecond)
	if e = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	plan, e = f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || plan.State != "COMPLETED" || plan.CheckCount != 2 {
		t.Fatalf("late query proof %v %v", plan, e)
	}
	after, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil || after.Effect.Outcome != "APPLIED" || after.Effect.LateEffect != "RULED_OUT" || !proto.Equal(after.Execution, before.Execution) || writes.Load() != 1 || queries.Load() != 2 || effects.Load() != 1 {
		t.Fatalf("late original effect %v %v", after, e)
	}
	queryIdentityMu.Lock()
	defer queryIdentityMu.Unlock()
	expected := a.OperationId.LocalId + "/" + before.Execution.Attempt.Ref.Name.LocalId + "/" + before.Execution.Attempt.ExternalKey + "/" + d.Binding.Resource
	if len(subjects) != 2 || subjects[0] != expected || subjects[1] != expected {
		t.Fatal("query identity drifted")
	}
	budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, a.TaskId)
	if e != nil || budget.Reserved != 40 {
		t.Fatalf("query fees lost: %v %v", budget, e)
	}
	p := completeProposal(t, f, []*v1.CompletionEvidence{{ConditionId: "created", OperationId: a.OperationId}})
	r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, &v1.BeginCompletionCommand{Header: header("api-query-completion"), TaskId: f.task.Name, ProposalRef: p})
	accepted(t, r, e)
	if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	result, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
	if e != nil || result == nil || result.Outcome != "SUCCEEDED" || writes.Load() != 1 || queries.Load() != 2 {
		t.Fatalf("query completion evidence%v %v", result, e)
	}
	assertAPIQueryTrace(t, f, plan)
	assertAPITraceExcludes(t, f, "synthetic-query-native-canary", keychain.Path(), d.Binding.Origin)
}

func TestAPIParameterSourceCrashRecoveryPublishesOriginalBodyBeforeSend(t *testing.T) {
	for _, point := range []string{"content.register", "body.accept", "content.publish", "trace.source_ack", "trace.index"} {
		for _, mode := range []sqlite.FaultMode{sqlite.CrashBeforeCommit, sqlite.CrashAfterCommit, sqlite.LoseReceipt} {
			t.Run(point+"/"+string(mode), func(t *testing.T) {
				var calls atomic.Int64
				target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					calls.Add(1)
					body, err := io.ReadAll(r.Body)
					if err != nil || string(body) != `{"quantity":9,"value":"api-source-body-canary-6719c096"}` {
						t.Error("target did not receive original published parameters")
					}
					_ = json.NewEncoder(w).Encode(map[string]any{"protocol": "lerna-reference-api-v1", "external_key": r.Header.Get("Idempotency-Key"), "attempt_id": r.Header.Get("Lerna-Attempt"), "account": r.Header.Get("Lerna-Account"), "origin": "http://" + r.Host, "applied": true, "terminal": true})
				}))
				defer target.Close()
				ctx, actor := context.Background(), &v1.Caller{UserId: "u", IssuerId: "host"}
				path := filepath.Join(t.TempDir(), "api-parameters.db")
				h, err := assembly.Open(path, "u", "d")
				if err != nil {
					t.Fatal(err)
				}
				admit := prepareAdmissionAdapter(t, h, target.URL, "api-reference-v1", 2)
				state, err := h.Tasks.QueryPlanning(ctx, actor, admit.TaskId)
				if err != nil {
					t.Fatal(err)
				}
				capability := state.Proposal.Step.CapabilityRef
				hdr := admissionHeader("api-parameter-source")
				hdr.Identity.TargetDomainId = "d/content"
				original := &v1.RegisterContentCommand{Header: hdr, TaskId: admit.TaskId, Body: []byte(` {"value":"api-source-body-canary-6719c096","quantity":9} `), MediaType: "application/json", SourceDescriptor: &v1.ContentSourceDescriptor{Kind: "HOST_IMPORT", Locator: "https://provider-private-source.invalid/local-path-canary", AcquisitionMethod: "LOCAL_IMPORT", ProviderVersion: "v1"}}
				encoded, err := proto.Marshal(original)
				if err != nil {
					t.Fatal(err)
				}
				if err = os.WriteFile(path+".parameters", encoded, 0600); err != nil {
					t.Fatal(err)
				}
				if err = h.Trace.Recover(ctx, actor); err != nil {
					t.Fatal(err)
				}
				if err = h.Close(); err != nil {
					t.Fatal(err)
				}
				child := exec.Command(os.Args[0], "-test.run=^TestAPIParameterSourceCrashChild$")
				child.Env = append(os.Environ(), "LERNA_API_PARAMETERS_DB="+path, "LERNA_API_PARAMETERS_POINT="+point, "LERNA_API_PARAMETERS_MODE="+string(mode))
				out, err := child.CombinedOutput()
				if mode == sqlite.LoseReceipt {
					if err != nil {
						t.Fatalf("child%v %s", err, out)
					}
				} else {
					var exit *exec.ExitError
					if !errors.As(err, &exit) || exit.ExitCode() != sqlite.CrashExitCode {
						t.Fatalf("fault not reached%v %s", err, out)
					}
				}
				if calls.Load() != 0 {
					t.Fatal("parameter source fault sent before P4/P5")
				}
				h, err = assembly.Open(path, "u", "d")
				if err != nil {
					t.Fatal(err)
				}
				r, err := h.Content.Register(ctx, actor, original)
				requireAccepted(t, r, err)
				if err = h.Content.ProcessRegistrations(ctx, actor); err != nil {
					t.Fatal(err)
				}
				body, err := h.Content.Read(ctx, actor, r.ResultRef)
				if err != nil || body.Status != "AVAILABLE" || string(body.RawBody) != string(original.Body) {
					t.Fatal("original parameter body changed during recovery", err)
				}
				snapshot, err := h.Tasks.RequestProposal(ctx, actor, &v1.RequestProposalCommand{Header: admissionHeader("imported-parameters-request"), TaskId: admit.TaskId})
				if err != nil {
					t.Fatal(err)
				}
				proposal, err := (&scripted.Reasoner{Step: &v1.ActionStep{StepId: "one", ParametersRef: r.ResultRef, CapabilityRef: capability}}).Propose(ctx, snapshot)
				if err != nil {
					t.Fatal(err)
				}
				r, err = h.Tasks.ReceiveProposal(ctx, actor, &v1.ReceiveProposalCommand{Header: admissionHeader("imported-parameters-proposal"), Proposal: proposal})
				requireAccepted(t, r, err)
				admit.ProposalRef = r.ResultRef
				h, keychain, a, start := prepareAPIStartFromAdmissionFault(t, h, path, admit)
				defer h.Close()
				r, err = h.Egress.Invoke(ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
				requireAccepted(t, r, err)
				op, err := h.Ledger.QueryOperation(ctx, actor, a.OperationId)
				if err != nil || op.Effect.Outcome != "APPLIED" || op.Effect.LateEffect != "RULED_OUT" || calls.Load() != 1 {
					t.Fatal("published parameter execution lost", err)
				}
				assertAPIRecoveredSources(t, h, op, 0, keychain.Path(), target.URL, "synthetic-api-fault-secret-f17e4038", "api-source-body-canary-6719c096", original.SourceDescriptor.Locator)
				sources, err := h.Trace.QuerySources(ctx, actor)
				if err != nil {
					t.Fatal(err)
				}
				staged, published := 0, 0
				for _, source := range sources {
					event := source.Command.Event
					if proto.Equal(event.SourceRecordRef, body.Ref) {
						if !proto.Equal(event.OriginCommand, original.Header.Identity) || !proto.Equal(event.BodyRef, body.Ref) || !proto.Equal(event.TaskId, admit.TaskId) {
							t.Fatal("parameter source identity changed")
						}
						if event.EventType == "CONTENT_STAGED" {
							staged++
						}
						if event.EventType == "CONTENT_PUBLISHED" {
							published++
						}
					}
				}
				if staged != 1 || published != 1 {
					t.Fatal("original parameter sources duplicated or omitted")
				}
			})
		}
	}
}

func TestAPIParametersRejectAmbiguousOrInjectedFields(t *testing.T) {
	for _, input := range []string{`{"value":null}`, `{"value":"x","value":"y"}`, `{"value":"x","quantity":"1"}`, `{"value":"x","quantity":1.0}`, `{"value":"x","quantity":1e0}`, `{"value":"x","quantity":-1}`, `{"value":"x","quantity":1000001}`, `{"value":"x","headers":{"Authorization":"evil"}}`, `{"value":"x"} {}`, string([]byte{'{', '"', 'v', 'a', 'l', 'u', 'e', '"', ':', '"', 0xff, '"', '}'})} {
		if got, err := command.CompileAPIParameters([]byte(input)); err == nil {
			t.Fatalf("accepted %q: %q", input, got)
		}
	}
}

func TestAPIQueryCurrentCapabilityReplacementStopsOldPlan(t *testing.T) {
	for _, mode := range []string{"replacement", "weakened"} {
		t.Run(mode, func(t *testing.T) {
			var writes, queries, effects, bills atomic.Int64
			target := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.Header.Get("Authorization") != "Bearer synthetic-api-deadline-secret" {
					t.Error("native credential missing")
					w.WriteHeader(401)
					return
				}
				bills.Add(1)
				if r.Method == "POST" {
					writes.Add(1)
					effects.Add(1)
					conn, _, err := w.(http.Hijacker).Hijack()
					if err != nil {
						t.Error(err)
						return
					}
					_ = conn.Close()
					return
				}
				if r.Method != "GET" {
					t.Error("unexpected method")
					w.WriteHeader(405)
					return
				}
				queries.Add(1)
				response := apiQueryResponse(r)
				response["applied"], response["terminal"] = false, false
				response["billing"] = apiQueryBoundaryBill(r, 2)
				_ = json.NewEncoder(w).Encode(response)
			})
			f := newFixtureWithTarget(t, 200, 200, false, target)
			d, queryCap, queryGrant := configureAPIQueryable(t, f, false)
			keychain := withAPIKeychain(t, f, d, []byte("synthetic-api-deadline-secret"))
			a, start := prepareStart(t, f)
			receipt, err := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
			accepted(t, receipt, err)
			before, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if err != nil {
				t.Fatal(err)
			}
			request := reconciliationCommand(f, a, queryCap, queryGrant)
			receipt, err = f.h.Ledger.RequestReconciliation(f.ctx, f.caller, request)
			accepted(t, receipt, err)
			if err = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			plan, err := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil || plan.State != "WAITING" || plan.CheckCount != 1 {
				t.Fatalf("weak query: %v %v", plan, err)
			}
			oldCapability, err := f.h.Tasks.QueryCapability(f.ctx, f.caller, queryCap)
			if err != nil {
				t.Fatal(err)
			}
			replacement := proto.Clone(oldCapability).(*v1.Capability)
			replacement.Ref, replacement.ApprovedBy = nil, nil
			if mode == "weakened" {
				replacement.ApiDescriptor.Queryable = false
				replacement.ApiDescriptor.Digest = command.APIDescriptorDigest(replacement.ApiDescriptor)
			}
			receipt, err = f.h.Tasks.ConfigureCapability(f.ctx, f.caller, &v1.ConfigureCapabilityCommand{Header: header("replace-query-cap"), Capability: replacement, Replaces: queryCap})
			accepted(t, receipt, err)
			if receipt.ResultRef.Revision != queryCap.Revision+1 {
				t.Fatal("query capability not replaced")
			}
			historical, err := f.h.Tasks.QueryCapability(f.ctx, f.caller, queryCap)
			if err != nil || !proto.Equal(historical, oldCapability) {
				t.Fatalf("old query descriptor changed: %v %v", historical, err)
			}
			time.Sleep(max(0, time.Until(time.UnixMilli(plan.NextReconcileAtUnixMs))) + 20*time.Millisecond)
			if err = f.h.Close(); err != nil {
				t.Fatal(err)
			}
			f.h, err = assembly.OpenWithOptions(f.path, "u", "d", assembly.Options{APIKeychainPath: keychain.Path()})
			if err != nil {
				t.Fatal(err)
			}
			plan, err = f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil || plan.State != "PAUSED" || plan.PauseReason != "CAPABILITY_UNAVAILABLE" || plan.CheckCount != 1 || len(plan.QueryRefs) != 1 {
				t.Fatalf("current capability gate: %v %v", plan, err)
			}
			after, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if err != nil || after.Effect.Outcome != "UNKNOWN" || after.Effect.LateEffect != "MAY_OCCUR" || !proto.Equal(before.Execution, after.Execution) {
				t.Fatalf("original responsibility: %v %v", after, err)
			}
			relation, err := f.h.Ledger.QueryReconciliationQuery(f.ctx, f.caller, plan.QueryRefs[0])
			if err != nil {
				t.Fatal(err)
			}
			query, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, relation.QueryOperationRef.Name)
			if err != nil || query.Lifecycle != "SETTLED" || !proto.Equal(query.QuerySubject.OperationId, a.OperationId) || !proto.Equal(query.QuerySubject.AttemptId, before.Execution.Attempt.Ref.Name) || query.QuerySubject.ExternalKey != before.Execution.Attempt.ExternalKey {
				t.Fatalf("query subject: %v %v", query, err)
			}
			source, err := f.h.Budget.QueryBillingSource(f.ctx, f.caller, query.Execution.Send.Ref)
			if err != nil || source.Amount == nil || *source.Amount != 2 || source.Status != "SETTLED" {
				t.Fatalf("query bill: %v %v", source, err)
			}
			budget, err := f.h.Budget.QueryBudget(f.ctx, f.caller, a.TaskId)
			if err != nil || budget.Reserved != 30 || budget.Settled != 2 {
				t.Fatalf("original and query fees: %v %v", budget, err)
			}
			if err = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			if writes.Load() != 1 || queries.Load() != 1 || effects.Load() != 1 || bills.Load() != 2 {
				t.Fatalf("target writes=%d queries=%d effects=%d bills=%d", writes.Load(), queries.Load(), effects.Load(), bills.Load())
			}
		})
	}
}

