			r, e := h.Sessions.CreateSession(ctx, caller, create)
			createReceipt := accepted(t, r, e)
			id := createReceipt.ResultRef.Name
			first := &v1.SubmitInputCommand{Header: header("original-goal"), SessionId: id, InputKind: "GOAL", ContentRef: stage(t, h, "original-goal-content", "original task")}
			r, e = h.Sessions.SubmitInput(ctx, caller, first)
			firstReceipt := accepted(t, r, e)
			session, e := h.Sessions.QuerySession(ctx, caller, id)
			if e != nil || len(session.GetTaskRefs()) != 1 || len(session.GetInputs()) != 1 || session.LastCommittedSeq != 1 {
				t.Fatalf("real original goal/session missing: %v %v", session, e)
			}
			oldRef := session.TaskRefs[0]
			old, e := h.Tasks.QueryTask(ctx, caller, oldRef.Name)
			if e != nil || old.GetLifecycle() != v1.TaskLifecycle_TASK_LIFECYCLE_OPEN {
				t.Fatalf("real original open task missing: %v %v", old, e)
			}
			var cancel *v1.SubmitInputCommand
			var cancelReceipt *v1.CommandReceipt
			var cancellation *v1.Cancellation
			if outcome == "CANCELLED" {
				cancel = &v1.SubmitInputCommand{Header: header("original-cancel"), SessionId: id, TaskId: old.TaskId, InputKind: "CONTROL", Control: "CANCEL", ExpectedControlGeneration: old.ControlGeneration}
				r, e = h.Sessions.SubmitInput(ctx, caller, cancel)
				cancelReceipt = accepted(t, r, e)
				if e = h.Tasks.ProcessCancellations(ctx, caller); e != nil {
					t.Fatal(e)
				}
				cancellation, e = h.Tasks.QueryCancellation(ctx, caller, old.TaskId)
				if e != nil || cancellation == nil || len(cancellation.AdmissionRefs) != 0 {
					t.Fatalf("real original cancellation missing: %v %v", cancellation, e)
				}
				old, e = h.Tasks.QueryTask(ctx, caller, oldRef.Name)
				if e != nil || old.Control != v1.TaskControl_TASK_CONTROL_CANCELLING {
					t.Fatalf("original cancel control missing: %v %v", old, e)
				}
			}
			closeHeader := header("original-close")
			closeHeader.Identity.IssuerId = "host"
			host := &v1.Caller{UserId: "alice", IssuerId: "host"}
			closeCommand := &v1.BeginTaskCloseCommand{Header: closeHeader, TaskRef: &v1.Ref{Name: old.TaskId, Revision: old.Revision, SchemaId: "lerna.v1.Task"}, ExpectedControlGeneration: old.ControlGeneration, Outcome: outcome, CloseReason: "USER_STOPPED"}
			if cancellation != nil {
				closeCommand.CancellationRef = cancellation.Ref
			}
			r, e = h.Tasks.BeginTaskClose(ctx, host, closeCommand)
			closeReceipt := accepted(t, r, e)
			if e = h.Tasks.ProcessTaskClosings(ctx, host); e != nil {
				t.Fatal(e)
			}
			closed, e := h.Tasks.QueryTaskClosingView(ctx, caller, old.TaskId)
			if e != nil || closed.GetTask().GetLifecycle() != v1.TaskLifecycle_TASK_LIFECYCLE_CLOSED || closed.GetResult().GetOutcome() != outcome || len(closed.Closing.AdmissionRefs) != 0 || len(closed.ClosureIntents) != 0 || len(closed.ClosureSeals) != 0 {
				t.Fatalf("owner protocol did not close original no-admission scope: %v %v", closed, e)
			}
			fixed, e := proto.MarshalOptions{Deterministic: true}.Marshal(closed.Result)
			if e != nil {
				t.Fatal(e)
			}
			oldPlanning, e := h.Tasks.QueryPlanning(ctx, caller, old.TaskId)
			if e != nil {
				t.Fatal(e)
			}
			prefix, e := h.Sessions.QuerySession(ctx, caller, id)
			prefixLength := 1
			if outcome == "CANCELLED" {
				prefixLength = 2
			}
			if e != nil || prefix.GetStatus() != "ACTIVE" || len(prefix.Inputs) != prefixLength || prefix.LastCommittedSeq != uint64(prefixLength) || !proto.Equal(prefix.TaskRefs[0], oldRef) {
				t.Fatalf("closing removed original session/history: %v %v", prefix, e)
			}
			record := &v1.SubmitInputCommand{Header: header("followup-record"), SessionId: id, InputKind: "RECORD", ObservedSessionSeq: prefix.LastCommittedSeq, ContentRef: stage(t, h, "followup-content", "follow-up after closing")}
			r, e = h.Sessions.SubmitInput(ctx, caller, record)
			recordReceipt := accepted(t, r, e)
			afterRecord, e := h.Sessions.QuerySession(ctx, caller, id)
			if e != nil || afterRecord.Revision != prefix.Revision+1 || afterRecord.LastCommittedSeq != uint64(prefixLength+1) || len(afterRecord.TaskRefs) != 1 {
				t.Fatalf("record changed old task association: %v %v", afterRecord, e)
			}
			input := afterRecord.Inputs[prefixLength]
			if input.TaskId != nil || input.RoutingStatus != "RECORDED" || input.InputKind != "RECORD" || !proto.Equal(input.CommandIdentity, record.Header.Identity) {
				t.Fatalf("follow-up implicitly targeted closed task: %v", input)
			}
			expected := afterRecord.Revision
			next := &v1.SubmitGoalCommand{Identity: header("new-goal").Identity, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "one distinct new task", Session: id, ExpectedRevision: &expected}
			r, e = h.Sessions.SubmitGoal(ctx, caller, next)
			if e != nil || r.GetPhase() != v1.ReceiptPhase_RECEIPT_PHASE_SUBMITTED {
				t.Fatalf("new same-session goal not saved: %v %v", r, e)
			}
			if e = h.Sessions.ProcessPending(ctx, caller); e != nil {
				t.Fatal(e)
			}
			q, e := h.Durable.QueryReceipt(ctx, caller, next.Identity)
			nextReceipt := accepted(t, q.GetReceipt(), e)
			if nextReceipt.TaskRef == nil || !proto.Equal(nextReceipt.SessionRef.Name, id) || proto.Equal(nextReceipt.TaskRef.Name, old.TaskId) {
				t.Fatalf("new goal did not create distinct task in original session: %v", nextReceipt)
			}
			complete, e := h.Sessions.QuerySession(ctx, caller, id)
			if e != nil || complete.Status != "ACTIVE" || len(complete.TaskRefs) != 2 || len(complete.Inputs) != prefixLength+2 || complete.LastCommittedSeq != uint64(prefixLength+2) || complete.Revision != afterRecord.Revision+1 || !proto.Equal(complete.TaskRefs[0], oldRef) || !proto.Equal(complete.TaskRefs[1], nextReceipt.TaskRef) {
				t.Fatalf("same-session history/one-new-task invariant failed: %v %v", complete, e)
			}
			for i, input := range complete.Inputs {
				if input.SessionSeq != uint64(i+1) || i < prefixLength && !proto.Equal(input, prefix.Inputs[i]) {
					t.Fatalf("original history or monotonic sequence changed: %v", input)
				}
			}
			newInput := complete.Inputs[prefixLength+1]
			if newInput.InputKind != "GOAL" || newInput.TaskInputSeq != 1 || !proto.Equal(newInput.TaskId, nextReceipt.TaskRef.Name) || !proto.Equal(newInput.CommandIdentity, next.Identity) {
				t.Fatalf("new task input not independent: %v", newInput)
			}
			newTask, e := h.Tasks.QueryTask(ctx, caller, nextReceipt.TaskRef.Name)
			if e != nil || newTask.GetLifecycle() != v1.TaskLifecycle_TASK_LIFECYCLE_OPEN {
				t.Fatalf("distinct new task not open: %v %v", newTask, e)
			}
			receipts := []*v1.CommandReceipt{createReceipt, firstReceipt, closeReceipt, recordReceipt, nextReceipt}
			if cancelReceipt != nil {
				receipts = append(receipts, cancelReceipt)
			}
			assertStable := func() {
				t.Helper()
				view, e := h.Tasks.QueryTaskClosingView(ctx, caller, old.TaskId)
				if e != nil || !proto.Equal(view, closed) {
					t.Fatalf("old closed task/control/closing/Result changed: %v %v", view, e)
				}
				b, e := proto.MarshalOptions{Deterministic: true}.Marshal(view.Result)
				if e != nil || !bytes.Equal(b, fixed) {
					t.Fatalf("old fixed Result bytes changed: %v", e)
				}
				planning, e := h.Tasks.QueryPlanning(ctx, caller, old.TaskId)
				if e != nil || !proto.Equal(planning, oldPlanning) {
					t.Fatalf("old planning/control basis changed: %v %v", planning, e)
				}
				session, e := h.Sessions.QuerySession(ctx, caller, id)
				if e != nil || !proto.Equal(session, complete) {
					t.Fatalf("replay/restart duplicated or rewrote session: %v %v", session, e)
				}
				task, e := h.Tasks.QueryTask(ctx, caller, nextReceipt.TaskRef.Name)
				if e != nil || !proto.Equal(task, newTask) {
					t.Fatalf("new original task changed: %v %v", task, e)
				}
				if cancellation != nil {
					scope, e := h.Tasks.QueryCancellation(ctx, caller, old.TaskId)
					if e != nil || !proto.Equal(scope, cancellation) {
						t.Fatalf("original cancellation responsibility changed: %v %v", scope, e)
					}
				}
				for _, receipt := range receipts {
					issuer := &v1.Caller{UserId: "alice", IssuerId: receipt.Identity.IssuerId}
					q, e := h.Durable.QueryReceipt(ctx, issuer, receipt.Identity)
					if e != nil || !proto.Equal(q.GetReceipt(), receipt) {
						t.Fatalf("original receipt changed: %v %v", q, e)
					}
				}
			}
			replay := func() {
				t.Helper()
				r, e := h.Sessions.CreateSession(ctx, caller, create)
				if !proto.Equal(accepted(t, r, e), createReceipt) {
					t.Fatal("session replay created another session")
				}
				r, e = h.Sessions.SubmitInput(ctx, caller, first)
				if !proto.Equal(accepted(t, r, e), firstReceipt) {
					t.Fatal("original goal receipt replay changed")
				}
				if cancel != nil {
					r, e = h.Sessions.SubmitInput(ctx, caller, cancel)
					if !proto.Equal(accepted(t, r, e), cancelReceipt) {
						t.Fatal("original cancellation replay changed")
					}
				}
				r, e = h.Tasks.BeginTaskClose(ctx, host, closeCommand)
				if !proto.Equal(accepted(t, r, e), closeReceipt) {
					t.Fatal("original closing replay changed")
				}
				r, e = h.Sessions.SubmitInput(ctx, caller, record)
				if !proto.Equal(accepted(t, r, e), recordReceipt) {
					t.Fatal("record replay changed")
				}
				r, e = h.Sessions.SubmitGoal(ctx, caller, next)
				if !proto.Equal(accepted(t, r, e), nextReceipt) {
					t.Fatal("new goal replay changed decided receipt")
				}
				if e = h.Sessions.ProcessPending(ctx, caller); e != nil {
					t.Fatal(e)
				}
			}
			assertStable()
			replay()
			assertStable()
			if e = h.Close(); e != nil {
				t.Fatal(e)
			}
			h, e = assembly.Open(path, "alice", "local")
			if e != nil {
				t.Fatal(e)
			}
			assertStable()
			replay()
			assertStable()
			t.Logf("outcome=%s session=%s retained_task=%s new_task=%s distinct_tasks=2 original_prefix=%d final_inputs=%d session_seq=%d old_admissions=0 Result_bytes=%d restart/replay_no_duplicates=true", outcome, id.LocalId, old.TaskId.LocalId, nextReceipt.TaskRef.Name.LocalId, prefixLength, len(complete.Inputs), complete.LastCommittedSeq, len(fixed))
		})
	}
}

func TestClosedUnknownMetricsAndStoppedBackupRetainOriginalResponsibilities(t *testing.T) {
	for _, outcome := range []string{"FAILED", "CANCELLED"} {
		t.Run(outcome, func(t *testing.T) {
			target := simulator.NewBillingTarget(3)
			target.Target = simulator.New("queryable")
			target.WithholdBill(true)
			f := newFixtureWithTarget(t, 200, 200, false, target)
			capability, grant := configureReconciliation(t, f)
			a, start := prepareStart(t, f)
			late := performWithoutObservation(t, f, a, start)
			r, err := f.h.Ledger.RequestReconciliation(f.ctx, f.caller, reconciliationCommand(f, a, capability, grant))
			accepted(t, r, err)
			closeReceipt, err := beginNonSuccessClose(t, f, "metric-original-close", outcome, "USER_STOPPED")
			accepted(t, closeReceipt, err)
			if err = processNonSuccessClosings(f, outcome); err != nil {
				t.Fatal(err)
			}
			view, err := f.h.Tasks.QueryTaskClosingView(f.ctx, f.caller, f.task.Name)
			if err != nil || view.Task.Lifecycle != v1.TaskLifecycle_TASK_LIFECYCLE_CLOSED || view.Result.GetOutcome() != outcome || len(view.Result.UnknownOperationRefs) != 1 || len(view.ExecutionFollowups) != 1 || len(view.SettlementFollowups) != 1 || len(view.FollowupJobs) != 2 {
				t.Fatalf("real closed UNKNOWN population: %v %v", view, err)
			}
			fixed, err := proto.Marshal(view.Result)
			if err != nil {
				t.Fatal(err)
			}
			original, err := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
			if err != nil {
				t.Fatal(err)
			}
			admissionReceipt, err := f.h.Durable.QueryReceipt(f.ctx, f.caller, header("admit").Identity)
			if err != nil {
				t.Fatal(err)
			}
			body, err := f.h.Content.Read(f.ctx, f.caller, f.parameters)
			if err != nil {
				t.Fatal(err)
			}
			egressCaller := &v1.Caller{UserId: "u", IssuerId: "egress"}
			dispatchIdentity := &v1.CommandIdentity{UserId: "u", IssuerId: "egress", TargetDomainId: "d/ledger", CommandId: "dispatch:" + original.Send.Ref.Name.LocalId}
			dispatchReceipt, err := f.h.Egress.QueryReceipt(f.ctx, egressCaller, dispatchIdentity)
			if err != nil {
				t.Fatal(err)
			}
			for _, job := range view.FollowupJobs {
				if job.State != "WAITING" {
					t.Fatalf("UNKNOWN responsibility missing: %v", job)
				}
			}
			assertClosedMetricsReadOnly(t, f, a, 1, &v1.ReconciliationMetrics{Total: 1, Active: 1, Ready: 1, Unfinished: 1, UnknownCovered: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			plan, err := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil {
				t.Fatal(err)
			}
			originalPlan := proto.Clone(plan).(*v1.Reconciliation)
			r, err = f.h.Ledger.ControlReconciliation(f.ctx, f.caller, &v1.ControlReconciliationCommand{Header: ledgerHeader("metric-closed-pause"), OperationId: a.OperationId, ExpectedRevision: plan.Ref.Revision, Action: "PAUSE"})
			accepted(t, r, err)
			assertClosedMetricsReadOnly(t, f, a, 1, &v1.ReconciliationMetrics{Total: 1, Paused: 1, Unfinished: 1, UnknownCovered: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			paused, err := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil {
				t.Fatal(err)
			}
			sourcePath := f.path
			backupDirectory := t.TempDir()
			manifest, err := f.h.CloseAndBackup(f.ctx, backupDirectory)
			if err != nil {
				t.Fatal(err)
			}
			t.Logf("actual stopped storage=%+v files=%+v", manifest.Environment, manifest.Files)
			stopped := stoppedFileSet(t, sourcePath)
			destination := t.TempDir()
			restored, err := assembly.RestoreBackup(f.ctx, backupDirectory, destination, "u", "d")
			if err != nil {
				t.Fatal(err)
			}
			f.h, f.path = restored, filepath.Join(destination, "state.db")
			assertStoppedFileSet(t, sourcePath, stopped)
			restoredView, err := f.h.Tasks.QueryTaskClosingView(f.ctx, f.caller, f.task.Name)
			if err != nil || !proto.Equal(restoredView.Closing, view.Closing) || !proto.Equal(restoredView.ClosureIntents[0], view.ClosureIntents[0]) || !proto.Equal(restoredView.ClosureSeals[0], view.ClosureSeals[0]) || !proto.Equal(restoredView.ExecutionFollowups[0], view.ExecutionFollowups[0]) || !proto.Equal(restoredView.SettlementFollowups[0], view.SettlementFollowups[0]) {
				t.Fatalf("restore changed original fixed responsibility: %v %v", restoredView, err)
			}
			plan, err = f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil || !proto.Equal(plan, paused) || !proto.Equal(plan.Ref.Name, originalPlan.Ref.Name) || !proto.Equal(plan.RequestedBy, originalPlan.RequestedBy) {
				t.Fatalf("restore replaced original paused plan: %v %v", plan, err)
			}
			actual, err := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
			if err != nil || !proto.Equal(actual, original) {
				t.Fatalf("restore replaced original execution: %v %v", actual, err)
			}
			closeAfter, err := f.h.Durable.QueryReceipt(f.ctx, f.caller, closeReceipt.Identity)
			if err != nil || !proto.Equal(closeAfter.GetReceipt(), closeReceipt) {
				t.Fatalf("restore replaced original closing receipt: %v %v", closeAfter, err)
			}
			admissionAfter, err := f.h.Durable.QueryReceipt(f.ctx, f.caller, admissionReceipt.Receipt.Identity)
			if err != nil || !proto.Equal(admissionAfter.GetReceipt(), admissionReceipt.Receipt) {
				t.Fatalf("restore replaced original admission receipt: %v %v", admissionAfter, err)
			}
			bodyAfter, err := f.h.Content.Read(f.ctx, f.caller, f.parameters)
			if err != nil || !proto.Equal(bodyAfter, body) {
				t.Fatalf("restore replaced original content: %v %v", bodyAfter, err)
			}
			r, err = f.h.Egress.Invoke(f.ctx, egressCaller, start)
			accepted(t, r, err)
			if !proto.Equal(r, dispatchReceipt.Receipt) {
				t.Fatal("restored original command changed its dispatch receipt")
			}
			requests, effects := target.Target.Snapshot()
			if len(requests) != 1 || requests[0].Method != "POST" || len(effects) != 1 || len(target.Bills()) != 1 {
				t.Fatal("restore/replay added a business send or rolled back the original target")
			}
			var output bytes.Buffer
			if err = (interaction.CLI{Metrics: f.h, Caller: f.caller, Domain: "d"}).Run(f.ctx, []string{"metrics"}, &output); err != nil {
				t.Fatal(err)
			}
			local := new(v1.LocalMetrics)
			if err = protojson.Unmarshal(output.Bytes(), local); err != nil || local.CrossDomainAtomic || local.Ledger.Unknown.Total != 1 || local.Ledger.Reconciliation.Paused != 1 || local.Trace.Diagnostics.Source.Availability != "DISABLED" || local.Trace.Diagnostics.Dropped != nil || local.Trace.Diagnostics.StalenessMs != nil {
				t.Fatalf("closed UNKNOWN CLI metric/missing boundary: %v %v", local, err)
			}
			assertClosedMetricsReadOnly(t, f, a, 1, &v1.ReconciliationMetrics{Total: 1, Paused: 1, Unfinished: 1, UnknownCovered: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			r, err = f.h.Ledger.ControlReconciliation(f.ctx, f.caller, &v1.ControlReconciliationCommand{Header: ledgerHeader("metric-closed-resume"), OperationId: a.OperationId, ExpectedRevision: plan.Ref.Revision, Action: "RESUME"})
			accepted(t, r, err)
			target.WithholdBill(false)
			target.Target.SetQueryBehavior("weak")
			if err = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			assertClosedMetricsReadOnly(t, f, a, 1, &v1.ReconciliationMetrics{Total: 1, Waiting: 1, Unfinished: 1, UnknownCovered: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			plan, err = f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
			if err != nil || len(plan.QueryRefs) != 1 {
				t.Fatalf("real weak query missing: %v %v", plan, err)
			}
			query, err := f.h.Ledger.QueryReconciliationQuery(f.ctx, f.caller, plan.QueryRefs[0])
			if err != nil || query.Work == nil || !proto.Equal(query.Work.OwnerRef.Name, originalPlan.Ref.Name) || !proto.Equal(query.Work.QuerySubject.AttemptId, original.Attempt.Ref.Name) || query.Work.QuerySubject.ExternalKey != original.Attempt.ExternalKey || query.AdmissionCommand == nil || query.AdmissionReceipt == nil || query.ObservationRef == nil {
				t.Fatalf("query replaced original plan or skipped real admission: %v %v", query, err)
			}
			evidence := stageBill(t, f, target.Bills()[0], "metric-original-late-bill")
			bill := &v1.ImportBillCommand{Header: header("metric-original-bill-import"), SendRef: original.Send.Ref, EvidenceRef: evidence}
			r, err = f.h.Budget.ImportBill(f.ctx, f.caller, bill)
			accepted(t, r, err)
			assertClosedMetricsReadOnly(t, f, a, 1, &v1.ReconciliationMetrics{Total: 1, Waiting: 1, Unfinished: 1, UnknownCovered: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			// 原费用到齐仍不证明原效果；原实际回报由自己的负责方处理。
			savePhysicalObservation(t, f, late)
			assertClosedMetricsReadOnly(t, f, a, 0, &v1.ReconciliationMetrics{Total: 1, Completed: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			if err = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			if err = f.h.Ledger.ProcessExecutionFollowups(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			if err = f.h.Budget.ProcessSettlementFollowups(f.ctx, f.caller); err != nil {
				t.Fatal(err)
			}
			assertClosedMetricsReadOnly(t, f, a, 0, &v1.ReconciliationMetrics{Total: 1, Completed: 1, DurationAvailability: "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS"}, fixed)
			finalView, err := f.h.Tasks.QueryTaskClosingView(f.ctx, f.caller, f.task.Name)
			if err != nil {
				t.Fatal(err)
			}
			for _, job := range finalView.FollowupJobs {
				if job.State != "COMPLETED" {
					t.Fatalf("original owner followup not complete: %v", job)
				}
			}
			r, err = f.h.Budget.ImportBill(f.ctx, f.caller, bill)
			accepted(t, r, err)
			duplicate := proto.Clone(bill).(*v1.ImportBillCommand)
			duplicate.Header = header("metric-original-bill-duplicate")
			r, err = f.h.Budget.ImportBill(f.ctx, f.caller, duplicate)
			accepted(t, r, err)
			budget, err := f.h.Budget.QueryBudget(f.ctx, f.caller, f.task.Name)
			if err != nil || budget.Settled != 6 || budget.Reserved != 0 {
				t.Fatalf("original and separate query fee/dedup: %v %v", budget, err)
			}
			current, err := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
			if err != nil || current.Attempt.Phase != "OBSERVED" || current.Send.Phase != "OBSERVED" || current.Attempt.Ref.Revision != original.Attempt.Ref.Revision+1 || current.Send.Ref.Revision != original.Send.Ref.Revision+1 || !proto.Equal(current.Send.ObservationRef.Name, late.Observation.Ref.Name) {
				t.Fatalf("original late observation was not accepted: %v %v", current, err)
			}
			// 原回报只推进原尝试、发送的阶段和版本；完整身份、开始回执、描述符与费用依据不变。
			unchanged := proto.Clone(current).(*v1.Execution)
			unchanged.Attempt.Phase, unchanged.Attempt.Ref.Revision = original.Attempt.Phase, original.Attempt.Ref.Revision
			unchanged.Send.Phase, unchanged.Send.Ref.Revision = original.Send.Phase, original.Send.Ref.Revision
			if !proto.Equal(unchanged, original) {
				t.Fatalf("late facts replaced original execution identity or binding: %v", current)
			}
			requests, effects = target.Target.Snapshot()
			if len(requests) != 2 || requests[0].Method != "POST" || requests[1].Method != "GET" || len(effects) != 1 || len(target.Bills()) != 2 {
				t.Fatal("metrics/late facts introduced another physical send or query effect")
			}
			assertStoppedFileSet(t, sourcePath, stopped)
			t.Logf("closed=%s originalUNKNOWN=1 currentUNKNOWN=0 originalPlan=1 completed=1 unfinished=0 independentPOST=1 GET=1 effects=1 bills=2 settled=6 reserved=0 fixedResult=true originalExecutionIdentity=true originalObservationAccepted=true sourceNeverResumed=true duration=MISSING", outcome)
		})
	}
}

func TestCommandIdentityRejectsConflictsAndKeepsOriginalDecision(t *testing.T) {
	ctx := context.Background()
	h, err := assembly.Open(filepath.Join(t.TempDir(), "lerna.db"), "alice", "local")
	if err != nil {
		t.Fatal(err)
	}
	defer h.Close()
	caller := &v1.Caller{UserId: "alice", IssuerId: "a:b"}
	cmd := &v1.SubmitGoalCommand{Identity: &v1.CommandIdentity{UserId: "alice", IssuerId: "a:b", TargetDomainId: "local", CommandId: "c"}, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "one"}
	if _, err := h.Sessions.SubmitGoal(ctx, caller, cmd); err != nil {
		t.Fatal(err)
	}
	if err := h.Sessions.ProcessPending(ctx, caller); err != nil {
		t.Fatal(err)
	}
	original, err := h.Durable.QueryReceipt(ctx, caller, cmd.Identity)
	if err != nil {
		t.Fatal(err)
	}
	cmd.Credential = "rotated"
	cmd.TraceId = "new-trace"
	duplicate, err := h.Sessions.SubmitGoal(ctx, caller, cmd)
	if err != nil {
		t.Fatal(err)
	}
	if duplicate.TaskRef.Name.LocalId != original.Receipt.TaskRef.Name.LocalId || duplicate.CommitPosition != original.Receipt.CommitPosition {
		t.Fatal("retry changed original decision")
	}
	cmd.Goal = "two"
	if _, err := h.Sessions.SubmitGoal(ctx, caller, cmd); err == nil || err.Error() != "IDEMPOTENCY_CONFLICT" {
		t.Fatalf("wanted conflict: %v", err)
	}
	caller.IssuerId = "a"
	cmd.Identity.IssuerId = "a"
	cmd.Identity.CommandId = "b:c"
	if _, err := h.Sessions.SubmitGoal(ctx, caller, cmd); err != nil {
		t.Fatalf("different issuer is independent: %v", err)
	}
	if err := h.Sessions.ProcessPending(ctx, caller); err != nil {
		t.Fatal(err)
	}
	second, err := h.Durable.QueryReceipt(ctx, caller, cmd.Identity)
	if err != nil {
		t.Fatal(err)
	}
	if second.Receipt.TaskRef.Name.LocalId == original.Receipt.TaskRef.Name.LocalId {
		t.Fatal("different command shared task")
	}
}

func TestCompletionCannotInventEvidenceOrIgnoreUnsettledEffects(t *testing.T) {
	for _, name := range []string{"missing-scope", "different-parameters", "missing-candidate", "foreign-candidate", "old-requirements", "unknown", "nonterminal", "conflicting", "user-evaluation"} {
		t.Run(name, func(t *testing.T) {
			target := simulator.New("idempotent")
			switch name {
			case "unknown":
				target.SetBehavior("drop-after-apply")
			case "nonterminal":
				target.SetBehavior("applied-not-terminal")
			case "conflicting":
				target.SetBehavior("contradictory")
			}
			f := newFixtureWithTarget(t, 100, 80, false, target)
			if name != "missing-scope" {
				scopeRequirement(t, f)
			}
			if name == "different-parameters" {
				var e error
				f.parameters, e = f.h.Content.Stage(f.ctx, f.caller, &v1.SubmitGoalCommand{Identity: header("different-body").Identity, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "a different request"})
				if e != nil {
					t.Fatal(e)
				}
			}
			if name == "user-evaluation" {
				task, e := f.h.Tasks.QueryTask(f.ctx, f.caller, f.task.Name)
				if e != nil {
					t.Fatal(e)
				}
				r, e := f.h.Tasks.AcceptRequirements(f.ctx, f.caller, &v1.AcceptRequirementsCommand{Header: header("evaluation-requirement"), TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, InputVersion: task.InputVersion, Source: "TRUSTED_TEMPLATE", Conditions: []*v1.Requirement{{ConditionId: "created", DescriptionRef: f.parameters, Necessary: true, VerificationRule: "USER_EVALUATION", RuleVersion: 1}}})
				accepted(t, r, e)
			}
			a, c := prepareStart(t, f)
			r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, c)
			accepted(t, r, e)
			if name == "old-requirements" {
				f.suffix = "replacement"
				scopeRequirement(t, f)
			}
			candidate := proto.Clone(a.OperationId).(*v1.GlobalName)
			if name == "foreign-candidate" {
				candidate.UserId = "other-user"
			}
			evidence := []*v1.CompletionEvidence{{ConditionId: "created", OperationId: candidate}}
			if name == "missing-candidate" {
				evidence = nil
			}
			p := completeProposal(t, f, evidence)
			r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, &v1.BeginCompletionCommand{Header: header("negative-begin"), TaskId: f.task.Name, ProposalRef: p})
			accepted(t, r, e)
			if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
				t.Fatal(e)
			}
			result, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
			if e != nil || result != nil {
				t.Fatalf("invented completion %v %v", result, e)
			}
			state, e := f.h.Tasks.QueryPlanning(f.ctx, f.caller, f.task.Name)
			if e != nil {
				t.Fatal(e)
			}
			v, e := f.h.Tasks.QueryVerification(f.ctx, f.caller, state.VerificationRef)
			if e != nil || v.Status != "VERIFYING" || len(v.Gaps) == 0 || state.VerificationFreeze != v.Round {
				t.Fatalf("missing lawful wait %v %v", v, e)
			}
			if name == "missing-scope" && !strings.Contains(strings.Join(v.Gaps, " "), "TARGET_SCOPE_MISSING") {
				t.Fatalf("missing specific scope gap %v", v.Gaps)
			}
			requests, _ := target.Snapshot()
			if len(requests) != 1 {
				t.Fatal("verification sent another request")
			}
		})
	}
}

func TestCompletionFreezesVerifiedResultAfterOneActualCall(t *testing.T) {
	target := simulator.New("idempotent")
	f := newFixtureWithTarget(t, 100, 80, false, target)
	task, e := f.h.Tasks.QueryTask(f.ctx, f.caller, f.task.Name)
	if e != nil {
		t.Fatal(e)
	}
	r, e := f.h.Tasks.AcceptRequirements(f.ctx, f.caller, &v1.AcceptRequirementsCommand{Header: header("scoped-requirements"), TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, InputVersion: task.InputVersion, Source: "TRUSTED_TEMPLATE", Conditions: []*v1.Requirement{{ConditionId: "created", DescriptionRef: f.parameters, Necessary: true, VerificationRule: "TARGET_RECORD", RuleVersion: 1, TargetRecord: &v1.TargetRecordAssertion{CapabilityRef: f.capability, ParametersRef: f.parameters}}}})
	accepted(t, r, e)
	a, c := prepareStart(t, f)
	r, e = f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, c)
	accepted(t, r, e)
	snap, e := f.h.Tasks.RequestProposal(f.ctx, f.caller, &v1.RequestProposalCommand{Header: header("complete-request"), TaskId: f.task.Name})
	if e != nil {
		t.Fatal(e)
	}
	proposal, e := (&scripted.Reasoner{CompletionEvidence: []*v1.CompletionEvidence{{ConditionId: "created", OperationId: a.OperationId}}}).Propose(f.ctx, snap)
	if e != nil {
		t.Fatal(e)
	}
	r, e = f.h.Tasks.ReceiveProposal(f.ctx, f.caller, &v1.ReceiveProposalCommand{Header: header("complete-proposal"), Proposal: proposal})
	accepted(t, r, e)
	start := &v1.BeginCompletionCommand{Header: header("begin-completion"), TaskId: f.task.Name, ProposalRef: r.ResultRef}
	r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, start)
	accepted(t, r, e)
	round, e := f.h.Tasks.QueryVerification(f.ctx, f.caller, r.ResultRef)
	if e != nil || round.Status != "VERIFYING" || round.ControlGeneration != snap.ControlGeneration+1 {
		t.Fatalf("round %v %v", round, e)
	}
	if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	result, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
	if e != nil || result == nil || result.Outcome != "SUCCEEDED" || len(result.Conditions) != 1 || result.Conditions[0].Conclusion != "SATISFIED" || len(result.Conditions[0].EvidenceRefs) == 0 || len(result.OperationRefs) != 1 {
		t.Fatalf("result %v %v", result, e)
	}
	task, e = f.h.Tasks.QueryTask(f.ctx, f.caller, f.task.Name)
	if e != nil || task.Lifecycle != v1.TaskLifecycle_TASK_LIFECYCLE_CLOSED || !proto.Equal(task.ResultRef, result.Ref) {
		t.Fatalf("task %v %v", task, e)
	}
	planning, e := f.h.Tasks.QueryPlanning(f.ctx, f.caller, f.task.Name)
	if e != nil || planning.VerificationFreeze != 0 {
		t.Fatalf("freeze %v %v", planning, e)
	}
	round, e = f.h.Tasks.QueryVerification(f.ctx, f.caller, result.VerificationRef)
	if e != nil || round.Status != "PASSED" {
		t.Fatalf("passed %v %v", round, e)
	}
	r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, start)
	accepted(t, r, e)
	if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	again, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
	if e != nil || !proto.Equal(result, again) {
		t.Fatalf("mutable result %v %v", again, e)
	}
	if e = f.h.Trace.Recover(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	traceView, e := f.h.Trace.Query(f.ctx, f.caller, &v1.TraceQuery{TaskId: f.task.Name})
	if e != nil {
		t.Fatal(e)
	}
	resultLinked, verificationLinked := false, false
	for _, event := range traceView.Events {
		if event.EventType == "RESULT_FIXED" && proto.Equal(event.SourceRecordRef, result.Ref) {
			resultLinked = true
		}
		if event.EventType == "VERIFICATION_CHANGED" && proto.Equal(event.SourceRecordRef, round.Ref) {
			verificationLinked = true
		}
	}
	if !resultLinked || !verificationLinked {
		t.Fatalf("missing completion authority links: %v", traceView)
	}
	requests, effects := target.Snapshot()
	if len(requests) != 1 || len(effects) != 1 {
		t.Fatalf("target requests=%d effects=%d", len(requests), len(effects))
	}
}

func TestCompletionRejectionDurablyRequestsOneContinuation(t *testing.T) {
	target := simulator.New("idempotent")
	target.SetBehavior("reject")
	f := newFixtureWithTarget(t, 100, 80, false, target)
	scopeRequirement(t, f)
	a, c := prepareStart(t, f)
	r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, c)
	accepted(t, r, e)
	p := completeProposal(t, f, []*v1.CompletionEvidence{{ConditionId: "created", OperationId: a.OperationId}})
	before, e := f.h.Tasks.QueryPlanning(f.ctx, f.caller, f.task.Name)
	if e != nil {
		t.Fatal(e)
	}
	r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, &v1.BeginCompletionCommand{Header: header("continue-begin"), TaskId: f.task.Name, ProposalRef: p})
	accepted(t, r, e)
	if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	next, e := f.h.Tasks.QueryPlanning(f.ctx, f.caller, f.task.Name)
	if e != nil || next.Snapshot == nil || proto.Equal(next.Snapshot.RequestRef, before.Snapshot.RequestRef) || next.Snapshot.PlanningGeneration != before.Snapshot.PlanningGeneration+1 || next.VerificationFreeze != 0 || next.Proposal != nil {
		t.Fatalf("rejection did not create a new durable request: %v %v", next, e)
	}
	v, e := f.h.Tasks.QueryVerification(f.ctx, f.caller, next.VerificationRef)
	if e != nil || v.Status != "REJECTED" || len(v.Gaps) == 0 || len(v.AdmissionRefs) != 1 || !proto.Equal(v.ContinuationRequestRef, next.Snapshot.RequestRef) {
		t.Fatalf("rejection facts %v %v", v, e)
	}
	req, e := f.h.Tasks.QueryProposalRequest(f.ctx, f.caller, next.Snapshot.RequestRef)
	if e != nil || req == nil || req.State != "PENDING" || req.Purpose != "PLAN" || !proto.Equal(req.SnapshotRef, next.Snapshot.Ref) {
		t.Fatalf("continuation responsibility %v %v", req, e)
	}
	job, e := f.h.Durable.QueryJob(f.ctx, f.caller, req.JobRef.Name)
	if e != nil || job == nil || job.State != "READY" || job.JobType != "PROPOSE" || !proto.Equal(job.SpecificationRef, req.Ref) {
		t.Fatalf("continuation work %v %v", job, e)
	}
	for range 2 {
		if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
			t.Fatal(e)
		}
	}
	if e = f.h.Close(); e != nil {
		t.Fatal(e)
	}
	f.h, e = assembly.Open(f.path, "u", "d")
	if e != nil {
		t.Fatal(e)
	}
	again, e := f.h.Tasks.QueryPlanning(f.ctx, f.caller, f.task.Name)
	if e != nil || !proto.Equal(again.Snapshot, next.Snapshot) || !proto.Equal(again.VerificationRef, next.VerificationRef) {
		t.Fatalf("restart repeated continuation %v %v", again, e)
	}
	assertTaskOwnerSource(t, f, "VERIFICATION_CHANGED", v.Ref, v.ContinuationRequestRef)
	assertTaskOwnerSource(t, f, "PROPOSAL_REQUESTED", next.Snapshot.Ref, req.Ref)
	requests, effects := target.Snapshot()
	if len(requests) != 1 || len(effects) != 0 {
		t.Fatalf("continuation resent old action: calls=%d effects=%d", len(requests), len(effects))
	}
}

