				t.Fatal(e)
			}
			originalSend, e := f.h.Ledger.QuerySend(f.ctx, f.caller, original.Send.Ref)
			if e != nil {
				t.Fatal(e)
			}
			budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil {
				t.Fatal(e)
			}
			if unknown && (budget.Reserved != 30 || budget.Settled != 0) || !unknown && (budget.Reserved != 0 || budget.Settled != 25) {
				t.Fatalf("original fee: %v", budget)
			}
			assertAbsent()
			p := completeProposal(t, f, []*v1.CompletionEvidence{{ConditionId: "created", OperationId: a.OperationId}})
			begin := &v1.BeginCompletionCommand{Header: header("trace-outage-completion"), TaskId: f.task.Name, ProposalRef: p}
			receipt, e := f.h.Tasks.BeginCompletion(f.ctx, f.caller, begin)
			accepted(t, receipt, e)
			if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
				t.Fatal(e)
			}
			result, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
			if e != nil || unknown && result != nil || !unknown && (result == nil || result.Outcome != "SUCCEEDED") {
				t.Fatalf("completion evidence: %v %v", result, e)
			}
			op, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if e != nil || unknown && op.Effect.Outcome != "UNKNOWN" || !unknown && op.Effect.Outcome != "APPLIED" {
				t.Fatalf("original effect: %v %v", op, e)
			}
			if !proto.Equal(original.Attempt, op.Execution.Attempt) || !proto.Equal(original.CallDescriptor, op.Execution.CallDescriptor) || !proto.Equal(original.Send.Ref.Name, op.Execution.Send.Ref.Name) {
				t.Fatal("completion replaced original execution")
			}
			sealed := proto.Clone(op.Execution).(*v1.Execution)
			for range 2 {
				if e = f.h.Ledger.ProcessReports(f.ctx, f.caller); e == nil {
					t.Fatal("trace sink recovered unexpectedly")
				}
				r, e = f.h.Tasks.BeginCompletion(f.ctx, f.caller, begin)
				accepted(t, r, e)
				if !proto.Equal(r, receipt) {
					t.Fatal("completion receipt changed")
				}
				if e = f.h.Tasks.ProcessCompletions(f.ctx, f.caller); e != nil {
					t.Fatal(e)
				}
				again, e := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
				if e != nil || !proto.Equal(result, again) {
					t.Fatalf("result changed: %v %v", again, e)
				}
				q, e := f.h.Egress.QueryReceipt(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, dispatch.Identity)
				if e != nil || !proto.Equal(dispatch, q.Receipt) {
					t.Fatalf("dispatch receipt changed: %v %v", q, e)
				}
				send, e := f.h.Ledger.QuerySend(f.ctx, f.caller, original.Send.Ref)
				if e != nil || !proto.Equal(send, originalSend) {
					t.Fatalf("historical send changed: %v %v", send, e)
				}
				x, e := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
				if e != nil || !proto.Equal(sealed, x) {
					t.Fatalf("execution changed: %v %v", x, e)
				}
				b, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
				if e != nil || !proto.Equal(budget, b) {
					t.Fatalf("fee changed: %v %v", b, e)
				}
				assertAbsent()
			}
			calls, effects := target.Target.Snapshot()
			if len(calls) != 1 || len(effects) != 1 || len(target.Bills()) != 1 || sink.queries < 3 {
				t.Fatalf("actual target or outage: calls=%d effects=%d bills=%d failures=%d", len(calls), len(effects), len(target.Bills()), sink.queries)
			}
		})
	}
}

func TestConcurrentModificationsHaveOneWinnerAndDependenciesNeverMisroute(t *testing.T) {
	h := open(t)
	id := session(t, h)
	task := goal(t, h, id)
	bind(t, h, task)
	text := stage(t, h, "changes", "change")
	results := make(chan *v1.CommandReceipt, 2)
	errors := make(chan error, 2)
	for _, name := range []string{"one", "two"} {
		go func(name string) {
			r, e := h.Sessions.SubmitInput(ctx, caller, &v1.SubmitInputCommand{Header: header(name), SessionId: id, TaskId: task.TaskId, InputKind: "MODIFY", ContentRef: text, ExpectedInputVersion: 1, ExpectedRequirementsVersion: 1})
			results <- r
			errors <- e
		}(name)
	}
	wins := 0
	for range 2 {
		r := <-results
		e := <-errors
		if e != nil {
			t.Fatal(e)
		}
		if r.Decision == v1.Decision_DECISION_ACCEPTED {
			wins++
		} else if r.Error.Code != "STALE_INPUT" {
			t.Fatalf("wrong conflict: %v", r)
		}
	}
	if wins != 1 {
		t.Fatalf("winners: %d", wins)
	}
	s, _ := h.Sessions.QuerySession(ctx, caller, id)
	if s.LastCommittedSeq != 2 {
		t.Fatalf("rejected input consumed sequence: %v", s)
	}
	c := &v1.SubmitInputCommand{Header: header("dependent"), SessionId: id, InputKind: "RECORD", ContentRef: text, DependsOn: []*v1.CommandIdentity{header("absent").Identity}}
	r, e := h.Sessions.SubmitInput(ctx, caller, c)
	accepted(t, r, e)
	s, _ = h.Sessions.QuerySession(ctx, caller, id)
	if s.Inputs[2].RoutingStatus != "WAITING_DEPENDENCY" {
		t.Fatal("unmet dependency ignored")
	}
}

func TestConcurrentRetriesHaveOnePendingJobAndOneTask(t *testing.T) {
	ctx := context.Background()
	h, err := assembly.Open(filepath.Join(t.TempDir(), "concurrent.db"), "alice", "local")
	if err != nil {
		t.Fatal(err)
	}
	defer h.Close()
	caller := &v1.Caller{UserId: "alice", IssuerId: "cli"}
	cmd := &v1.SubmitGoalCommand{Identity: &v1.CommandIdentity{UserId: "alice", IssuerId: "cli", TargetDomainId: "local", CommandId: "same"}, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "exactly one"}
	errors := make(chan error, 8)
	for i := 0; i < 8; i++ {
		go func() { _, err := h.Sessions.SubmitGoal(ctx, caller, cmd); errors <- err }()
	}
	for i := 0; i < 8; i++ {
		if err := <-errors; err != nil {
			t.Fatal(err)
		}
	}
	jobs, err := h.Durable.Pending(ctx, caller)
	if err != nil || len(jobs) != 1 {
		t.Fatalf("duplicate jobs: %v %v", jobs, err)
	}
	for i := 0; i < 8; i++ {
		go func() { errors <- h.Sessions.ProcessPending(ctx, caller) }()
	}
	for i := 0; i < 8; i++ {
		if err := <-errors; err != nil {
			t.Fatal(err)
		}
	}
	q, err := h.Durable.QueryReceipt(ctx, caller, cmd.Identity)
	if err != nil {
		t.Fatal(err)
	}
	session, err := h.Sessions.QuerySession(ctx, caller, q.Receipt.SessionRef.Name)
	if err != nil || len(session.TaskRefs) != 1 || session.LastCommittedSeq != 1 {
		t.Fatalf("duplicate tasks: %v %v", session, err)
	}
}

func TestConfirmationLifecycleCommitBoundaries(t *testing.T) {
	for kind, point := range confirmationFaultPoints {
		for _, mode := range []sqlite.FaultMode{sqlite.CrashBeforeCommit, sqlite.CrashAfterCommit, sqlite.LoseReceipt} {
			t.Run(kind+"/"+string(mode), func(t *testing.T) {
				var calls atomic.Int64
				target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { calls.Add(1); w.WriteHeader(200) }))
				defer target.Close()
				path := filepath.Join(t.TempDir(), "confirmation.db")
				h, e := assembly.Open(path, "u", "d")
				if e != nil {
					t.Fatal(e)
				}
				c := prepareConfirmationFault(t, h, target.URL, kind)
				h.Close()
				b, e := proto.Marshal(c)
				if e != nil {
					t.Fatal(e)
				}
				if e = os.WriteFile(path+".command", b, 0600); e != nil {
					t.Fatal(e)
				}
				if mode == sqlite.LoseReceipt {
					h, e = assembly.Open(path, "u", "d")
					if e != nil {
						t.Fatal(e)
					}
					ctx, e := sqlite.WithFault(context.Background(), point, mode)
					if e != nil {
						t.Fatal(e)
					}
					r, e := runConfirmationFault(h, ctx, c)
					if e == nil || r != nil {
						t.Fatalf("lost receipt: %v %v", r, e)
					}
					h.Close()
				} else {
					child := exec.Command(os.Args[0], "-test.run=^TestConfirmationLifecycleCrashChild$")
					child.Env = append(os.Environ(), "LERNA_CONFIRMATION_DB="+path, "LERNA_CONFIRMATION_KIND="+kind, "LERNA_CONFIRMATION_MODE="+string(mode))
					out, e := child.CombinedOutput()
					var exit *exec.ExitError
					if !errors.As(e, &exit) || exit.ExitCode() != sqlite.CrashExitCode {
						t.Fatalf("fault not hit: %v %s", e, out)
					}
				}
				h, e = assembly.Open(path, "u", "d")
				if e != nil {
					t.Fatal(e)
				}
				defer h.Close()
				ctx := context.Background()
				caller := &v1.Caller{UserId: "u", IssuerId: "host"}
				q, e := h.Durable.QueryReceipt(ctx, caller, c.GetHeader().Identity)
				if e != nil {
					t.Fatal(e)
				}
				if mode == sqlite.CrashBeforeCommit {
					if q.State != v1.ReceiptQueryState_RECEIPT_QUERY_STATE_NOT_FOUND {
						t.Fatalf("partial decision: %v", q)
					}
				} else if q.State != v1.ReceiptQueryState_RECEIPT_QUERY_STATE_DECIDED {
					t.Fatalf("lost decision: %v", q)
				}
				if ac, ok := c.(*v1.AdmitCommand); ok && mode == sqlite.CrashBeforeCommit {
					confirmation, e := h.Sessions.QueryCurrentConfirmation(ctx, caller, ac.ConfirmationRef.Name)
					if e != nil || confirmation.State != "APPROVED" {
						t.Fatalf("partial consumption: %v %v", confirmation, e)
					}
					uses, e := h.Grants.QueryUses(ctx, caller, ac.TaskId)
					if e != nil || len(uses) != 0 {
						t.Fatalf("partial use: %v %v", uses, e)
					}
					budget, e := h.Budget.QueryBudget(ctx, caller, nil)
					if e != nil || budget.Reserved != 0 {
						t.Fatalf("partial budget: %v %v", budget, e)
					}
				}
				r, e := runConfirmationFault(h, ctx, c)
				requireAccepted(t, r, e)
				if mode != sqlite.CrashBeforeCommit && !proto.Equal(r, q.Receipt) {
					t.Fatal("original receipt changed")
				}
				switch kind {
				case "operation-request", "grant-request", "approve", "withdraw":
					confirmation, e := h.Sessions.QueryConfirmation(ctx, caller, r.ResultRef)
					if e != nil || confirmation == nil {
						t.Fatalf("missing confirmation: %v %v", confirmation, e)
					}
					expected := "PENDING"
					if kind == "approve" {
						expected = "APPROVED"
					}
					if kind == "withdraw" {
						expected = "WITHDRAWN"
					}
					if confirmation.State != expected {
						t.Fatalf("confirmation state: %v", confirmation)
					}
					session, e := h.Sessions.QuerySession(ctx, caller, confirmation.SessionId)
					expectedEvents := 1
					if kind == "approve" {
						expectedEvents = 2
					}
					if kind == "withdraw" {
						expectedEvents = 3
					}
					if e != nil || len(session.Inputs) != expectedEvents {
						t.Fatalf("confirmation events: %v %v", session, e)
					}
					for _, input := range session.Inputs[1:] {
						delivery, e := h.Sessions.QueryInput(ctx, caller, &v1.Ref{Name: input.InputId, Revision: 1, SchemaId: "lerna.v1.SessionInput"})
						if e != nil || delivery == nil || !proto.Equal(delivery.Input, input) {
							t.Fatalf("missing exact event: %v %v", delivery, e)
						}
					}
				case "issue":
					grant, e := h.Grants.QueryGrant(ctx, caller, r.ResultRef)
					if e != nil || grant == nil || grant.Status != "ACTIVE" {
						t.Fatalf("missing grant: %v %v", grant, e)
					}
					confirmation, e := h.Sessions.QueryCurrentConfirmation(ctx, caller, c.(*v1.IssueGrantCommand).ConfirmationRef.Name)
					if e != nil || confirmation.State != "CONSUMED" || confirmation.GetConsumedGrantIssuanceRef() == nil {
						t.Fatalf("missing issuance consumption: %v %v", confirmation, e)
					}
				case "revoke":
					grant, e := h.Grants.QueryCurrentGrant(ctx, caller, c.(*v1.RevokeGrantCommand).GrantId)
					if e != nil || grant.Status != "REVOKED" || grant.RevocationCompletion != "COMPLETE" {
						t.Fatalf("missing revocation: %v %v", grant, e)
					}
				case "admit":
					ac := c.(*v1.AdmitCommand)
					confirmation, e := h.Sessions.QueryCurrentConfirmation(ctx, caller, ac.ConfirmationRef.Name)
					if e != nil || confirmation.State != "CONSUMED" || !proto.Equal(confirmation.GetConsumedAdmissionRef(), r.ResultRef) {
						t.Fatalf("missing consumption: %v %v", confirmation, e)
					}
					uses, e := h.Grants.QueryUses(ctx, caller, ac.TaskId)
					if e != nil || len(uses) != 1 {
						t.Fatalf("duplicate use: %v %v", uses, e)
					}
				}
				if calls.Load() != 0 {
					t.Fatal("authority command called target")
				}
				if e = h.Trace.Recover(ctx, caller); e != nil {
					t.Fatal(e)
				}
				sources, e := h.Trace.QuerySources(ctx, caller)
				if e != nil {
					t.Fatal(e)
				}
				for _, source := range sources {
					event := source.Command.Event
					if event.SourceRecordRef.GetSchemaId() != "lerna.v1.Confirmation" || event.Producer != "sessions" {
						continue
					}
					original, e := h.Sessions.QueryConfirmation(ctx, caller, event.SourceRecordRef)
					if e != nil || original == nil || event.EventType != "CONFIRMATION_"+original.State {
						t.Fatalf("source escaped original confirmation transaction: %v %v", event, e)
					}
					confirmationSource(t, h, ctx, caller, original)
					indexed, e := h.Trace.QueryEvent(ctx, caller, event.Ref)
					if e != nil || source.Receipt == nil || !proto.Equal(indexed, event) {
						t.Fatalf("confirmation source recovery lost original: %v %v", indexed, e)
					}
				}
			})
		}
	}
}

func TestConfirmedRawPayloadMatchesDisplayedAndSentBytes(t *testing.T) {
	for _, tc := range []struct {
		name            string
		body            []byte
		encoding, value string
	}{
		{"binary", []byte{0, 255, 128, 'x', 0}, "BASE64", "AP+AeAA="},
		{"empty", []byte{}, "UTF-8", ""},
		{"utf8-with-nul", []byte("raw\x00body"), "UTF-8", "raw\x00body"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			received := make(chan []byte, 2)
			target := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				b, e := io.ReadAll(r.Body)
				if e != nil {
					t.Error(e)
				}
				received <- b
				w.Header().Set("Content-Type", "application/octet-stream")
				_, _ = w.Write(tc.body)
			})
			f := newFixtureWithTarget(t, 100, 80, false, target)
			first, start := prepareStart(t, f)
			r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
			accepted(t, r, e)
			<-received
			x, e := f.h.Ledger.QueryExecution(f.ctx, f.caller, first.OperationId)
			if e != nil {
				t.Fatal(e)
			}
			raw, e := f.h.Ledger.QueryObservation(f.ctx, f.caller, x.Send.ObservationRef)
			if e != nil {
				t.Fatal(e)
			}
			r, e = f.h.Sessions.SubmitGoal(f.ctx, f.caller, &v1.SubmitGoalCommand{Identity: header("raw-confirmed-goal").Identity, ContractVersion: 1, FingerprintVersion: 1, SchemaId: "lerna.v1.SubmitGoal", Goal: "send confirmed observed bytes"})
			if e != nil {
				t.Fatal(e)
			}
			if e = f.h.Sessions.ProcessPending(f.ctx, f.caller); e != nil {
				t.Fatal(e)
			}
			goal, e := f.h.Durable.QueryReceipt(f.ctx, f.caller, r.Identity)
			if e != nil {
				t.Fatal(e)
			}
			f.task = goal.Receipt.TaskRef
			r, e = f.h.Tasks.AcceptRequirements(f.ctx, f.caller, &v1.AcceptRequirementsCommand{Header: header("raw-requirements"), TaskRef: f.task, InputVersion: 1, Source: "TRUSTED_TEMPLATE", Conditions: []*v1.Requirement{{ConditionId: "created", DescriptionRef: goal.Receipt.InputRef, Necessary: true, VerificationRule: "TARGET_RECORD", RuleVersion: 1}}})
			accepted(t, r, e)
			r, e = f.h.Budget.Configure(f.ctx, f.caller, &v1.ConfigureBudgetCommand{Header: header("raw-budget"), TaskId: f.task.Name, Unit: "USD_MICRO", Limit: 80})
			accepted(t, r, e)
			g, e := f.h.Grants.QueryGrant(f.ctx, f.caller, f.grant)
			if e != nil {
				t.Fatal(e)
			}
			g.Ref = nil
			g.Issuer = nil
			g.Status = ""
			g.UsePoolId = ""
			g.Subject = f.task.Name
			g.UseMode = "SINGLE"
			g.MaxAdmissions = 1
			g.ConfirmationRequired = true
			g.Permissions[0].ParameterMode = "EXACT"
			g.Permissions[0].ParametersRef = raw.BodyRef
			r, e = f.h.Grants.RequestGrantConfirmation(f.ctx, f.caller, &v1.RequestGrantConfirmationCommand{Header: header("raw-grant-request"), Grant: g})
			accepted(t, r, e)
			grantMatter, e := f.h.Sessions.ReadConfirmation(f.ctx, f.caller, r.ResultRef)
			if e != nil {
				t.Fatal(e)
			}
			type parameters struct{ Encoding, Value, MediaType string }
			var grantDescription struct{ Parameters []parameters }
			if e = json.Unmarshal([]byte(grantMatter.Description), &grantDescription); e != nil {
				t.Fatal(e)
			}
			expected := parameters{tc.encoding, tc.value, "application/octet-stream"}
			if len(grantDescription.Parameters) != 1 || grantDescription.Parameters[0] != expected {
				t.Fatalf("grant displays different bytes: %s", grantMatter.Description)
			}
			r, e = f.h.Sessions.RespondConfirmation(f.ctx, f.caller, &v1.RespondConfirmationCommand{Header: header("raw-grant-approve"), ConfirmationRef: grantMatter.Ref, BindingDigest: grantMatter.BindingDigest, Decision: "APPROVE"})
			accepted(t, r, e)
			r, e = f.h.Grants.IssueGrant(f.ctx, f.caller, &v1.IssueGrantCommand{Header: header("raw-grant-issue"), ConfirmationRef: r.ResultRef})
			accepted(t, r, e)
			f.grant = r.ResultRef
			f.parameters = raw.BodyRef
			f.suffix = "-confirmed-raw"
			proposal := f.propose(t, nil)
			r, e = f.h.Tasks.RequestAdmissionConfirmation(f.ctx, f.caller, &v1.RequestAdmissionConfirmationCommand{Header: header("raw-action-request"), TaskId: f.task.Name, ProposalRef: proposal, GrantRef: f.grant})
			accepted(t, r, e)
			actionMatter, e := f.h.Sessions.ReadConfirmation(f.ctx, f.caller, r.ResultRef)
			if e != nil {
				t.Fatal(e)
			}
			var actionDescription struct{ Parameters parameters }
			if e = json.Unmarshal([]byte(actionMatter.Description), &actionDescription); e != nil {
				t.Fatal(e)
			}
			if actionDescription.Parameters != expected {
				t.Fatalf("action displays different bytes: %s", actionMatter.Description)
			}
			r, e = f.h.Sessions.RespondConfirmation(f.ctx, f.caller, &v1.RespondConfirmationCommand{Header: header("raw-action-approve"), ConfirmationRef: actionMatter.Ref, BindingDigest: actionMatter.BindingDigest, Decision: "APPROVE"})
			accepted(t, r, e)
			r, e = f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("raw-admit"), TaskId: f.task.Name, ProposalRef: proposal, GrantRef: f.grant, ConfirmationRef: r.ResultRef})
			accepted(t, r, e)
			a, e := f.h.Tasks.QueryAdmission(f.ctx, f.caller, r.ResultRef)
			if e != nil {
				t.Fatal(e)
			}
			if e = f.h.Tasks.ProcessHandoffs(f.ctx, f.caller); e != nil {
				t.Fatal(e)
			}
			claim, e := f.h.LedgerWork.ExecuteJob(f.ctx, f.caller, &v1.JobCommand{Identity: ledgerHeader("raw-claim").Identity, ContractVersion: 1, Action: "CLAIM", AllowedTypes: []string{"EXECUTE_OPERATION"}, Limit: 100, LeaseMs: 30000, ProcessInstance: "raw-worker"})
			accepted(t, claim, e)
			var executionClaim *v1.Job
			for _, job := range claim.Jobs {
				if proto.Equal(job.SpecificationRef.Name, a.OperationId) {
					executionClaim = job
					break
				}
			}
			if executionClaim == nil {
				t.Fatal("operation claim missing")
			}
			r, e = f.h.Ledger.Prepare(f.ctx, f.caller, &v1.PrepareExecutionCommand{Header: ledgerHeader("raw-prepare"), OperationId: a.OperationId, ProcessInstance: "raw-worker", Claim: executionClaim})
			accepted(t, r, e)
			x, e = f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
			if e != nil {
				t.Fatal(e)
			}
			binding := &v1.ExitCredentialBinding{UserId: "u", TaskId: a.TaskId, SubjectId: a.TaskId, OperationId: a.OperationId, AttemptId: x.Attempt.Ref.Name, SendSeq: x.Send.SendSeq, AdmissionRef: a.Ref, GrantUseRef: a.GrantUseRef, CallerIssuerId: "egress", Audience: "egress", ExecutorEndpointId: a.ExecutorEndpointId, ExecutorInstance: x.Send.ProcessInstance, DescriptorDigest: x.CallDescriptor.Digest, UseRight: a.CapabilitySnapshot.UseRight, ProcessingPurpose: a.CapabilitySnapshot.ProcessingPurpose, RequirementsVersion: a.RequirementsVersion, InputVersion: a.InputVersion, ControlGeneration: a.ControlGeneration, BudgetReservationRef: a.BudgetBasis.ReservationRef}
			r, e = f.h.Grants.IssueCredential(f.ctx, f.caller, &v1.IssueExitCredentialCommand{Header: header("raw-credential"), AdmissionRef: a.Ref, Binding: binding, ExpiresAtUnixMs: time.Now().Add(time.Minute).UnixMilli()})
			accepted(t, r, e)
			sh := header("start:" + x.Send.Ref.Name.LocalId)
			sh.Identity.IssuerId = "egress"
			r, e = f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, &v1.StartExecutionCommand{Header: sh, AdmissionRef: a.Ref, CredentialRef: r.ResultRef, Binding: binding, Claim: executionClaim, CallDescriptor: x.CallDescriptor})
			accepted(t, r, e)
			if actual := <-received; !bytes.Equal(actual, tc.body) {
