		"operation": func() error { _, e := f.h.Ledger.QueryOperationVersion(f.ctx, f.caller, forged(op.Ref)); return e },
		"raw":       func() error { _, e := f.h.Ledger.QueryObservation(f.ctx, f.caller, forged(raw.Ref)); return e },
