func TestExecutionDeclarationPreservesUnknownQueryBoundsOriginalProofAndBilling(t *testing.T) {
	for _, behavior := range []string{"terminal", "applied-not-terminal"} {
		t.Run(behavior, func(t *testing.T) {
			target := simulator.New("idempotent")
			if behavior != "terminal" {
				target.SetBehavior(behavior)
			}
			f := newFixtureWithTarget(t, 100, 80, false, target)
			a, start := prepareStart(t, f)
			r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
			accepted(t, r, e)
			op, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if e != nil {
				t.Fatal(e)
			}
			declaration := op.Execution.Attempt.Capabilities
			assertUnknownQueryBounds(t, declaration)
			if declaration.ProtocolVersion != "lerna-simulator-v1" || declaration.VerificationBasis != "reference-target-v1" || declaration.DeclarationVersion != "1" || declaration.Effect != "ATOMIC_WRITE" || !declaration.Idempotent || declaration.Queryable {
				t.Fatalf("original fixed declaration changed: %v", declaration)
			}
			admission, e := f.h.Tasks.QueryAdmission(f.ctx, f.caller, op.AdmissionRef)
			if e != nil || op.CapabilitySnapshot.FeeCeiling == nil || *op.CapabilitySnapshot.FeeCeiling != 30 || op.CapabilitySnapshot.Nonbillable || admission.BudgetBasis.Ceiling != 30 || !proto.Equal(op.CapabilitySnapshot.RateBasisRef, admission.BudgetBasis.RateBasisRef) {
				t.Fatalf("billing dimension left original capability/budget basis: %v %v", admission, e)
			}
			interpreted, e := f.h.Ledger.InterpretObservation(f.ctx, f.caller, &v1.InterpretObservationCommand{Header: ledgerHeader("declaration-original-proof"), ObservationRef: op.Execution.Send.ObservationRef})
			accepted(t, interpreted, e)
			finding, e := f.h.Ledger.QueryInterpretation(f.ctx, f.caller, interpreted.ResultRef)
			if e != nil || finding.Rule != "reference-target-v1" || finding.Outcome != "APPLIED" || behavior == "terminal" && finding.LateEffect != "RULED_OUT" || behavior != "terminal" && finding.LateEffect != "MAY_OCCUR" {
				t.Fatalf("declaration rule was confused with an outcome guarantee: %v %v", finding, e)
			}
			if e = f.h.Close(); e != nil {
				t.Fatal(e)
			}
			f.h, e = assembly.Open(f.path, "u", "d")
			if e != nil {
				t.Fatal(e)
			}
			restored, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			requests, effects := target.Snapshot()
			if e != nil || !proto.Equal(op.Execution, restored.Execution) || !proto.Equal(op.CapabilitySnapshot, restored.CapabilitySnapshot) || len(requests) != 1 || len(effects) != 1 || f.calls.Load() != 1 {
				t.Fatalf("recovery upgraded declaration, billing or original request: %v %v", restored, e)
			}
		})
	}
}

func TestExplicitClarificationCompletesOriginalGoalInInputOrder(t *testing.T) {
	h := open(t)
	id := session(t, h)
	task := goal(t, h, id)
	host := &v1.Caller{UserId: "alice", IssuerId: "host"}
	hdr := header("ask-for-conditions")
	hdr.Identity.IssuerId = "host"
	r, e := h.Tasks.ProcessInput(ctx, host, &v1.ProcessInputCommand{Header: hdr, TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, InputVersion: 1, Outcome: "CLARIFY"})
	accepted(t, r, e)
	task, _ = h.Tasks.QueryTask(ctx, caller, task.TaskId)
	hdr = header("explicit-question")
	hdr.Identity.IssuerId = "host"
	r, e = h.Sessions.PublishQuestion(ctx, host, &v1.PublishQuestionCommand{Header: hdr, SessionId: id, TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, ContentRef: task.GoalRef, ChangesBasis: true, ExpiresAtUnixMs: 4102444800000})
	question := accepted(t, r, e).ResultRef
	conditions := []*v1.Requirement{{ConditionId: "clarified", DescriptionRef: task.GoalRef, Necessary: true, VerificationRule: "USER_EVALUATION", RuleVersion: 1}}
	r, e = h.Sessions.SubmitInput(ctx, caller, &v1.SubmitInputCommand{Header: header("explicit-answer"), SessionId: id, InputKind: "ANSWER", TaskId: task.TaskId, RequestRef: question, ContentRef: task.GoalRef, ExpectedInputVersion: 1, ExpectedRequirementsVersion: 1, ExplicitConditions: conditions})
	answer := accepted(t, r, e).ResultRef
	for _, version := range []uint64{1, 2} {
		task, _ = h.Tasks.QueryTask(ctx, caller, task.TaskId)
		hdr = header(fmt.Sprintf("bind-clarification-%d", version))
		hdr.Identity.IssuerId = "host"
		r, e = h.Tasks.ProcessInput(ctx, host, &v1.ProcessInputCommand{Header: hdr, TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, InputVersion: version, Outcome: "REPLACE", Source: "USER_EXPLICIT", Conditions: conditions, SourceInputRef: answer})
		accepted(t, r, e)
		task, _ = h.Tasks.QueryTask(ctx, caller, task.TaskId)
		if task.BoundInputVersion != version {
			t.Fatalf("skipped processing order: %v", task)
		}
		if version == 1 {
			proposal := propose(t, h, task, "clarifying")
			r, e = h.Tasks.Admit(ctx, caller, &v1.AdmitCommand{Header: header("clarification-intermediate-admit"), TaskId: task.TaskId, ProposalRef: proposal})
			if e != nil || r.GetError().GetCode() != "REQUIREMENTS_NOT_ACCEPTED" {
				t.Fatalf("intermediate input bypass: %v %v", r, e)
			}
		}
	}
	p, e := h.Tasks.QueryPlanning(ctx, caller, task.TaskId)
	if e != nil || p.Requirements.Source != "USER_EXPLICIT" || !proto.Equal(p.Requirements.SourceInputRef, answer) || task.BoundInputVersion != 2 || len(task.WaitingOn) != 0 {
		t.Fatalf("clarification unresolved: %v %v %v", task, p, e)
	}
}

