func TestIndependentConnectionsAcceptOnlyOneAnswerAndUseCoreOrder(t *testing.T) {
	path := filepath.Join(t.TempDir(), "two-connections.db")
	h, e := assembly.Open(path, "alice", "local")
	if e != nil {
		t.Fatal(e)
	}
	defer h.Close()
	id := session(t, h)
	task := goal(t, h, id)
	bind(t, h, task)
	task, _ = h.Tasks.QueryTask(ctx, caller, task.TaskId)
	hdr := header("race-question")
	hdr.Identity.IssuerId = "host"
	r, e := h.Sessions.PublishQuestion(ctx, &v1.Caller{UserId: "alice", IssuerId: "host"}, &v1.PublishQuestionCommand{Header: hdr, SessionId: id, TaskRef: &v1.Ref{Name: task.TaskId, Revision: task.Revision, SchemaId: "lerna.v1.Task"}, ContentRef: task.GoalRef, ExpiresAtUnixMs: 4102444800000, ChangesBasis: true})
	question := accepted(t, r, e).ResultRef
	other, e := assembly.Open(path, "alice", "local")
	if e != nil {
		t.Fatal(e)
	}
	defer other.Close()
	type result struct {
		r *v1.CommandReceipt
		e error
	}
	results := make(chan result, 2)
	for i, harness := range []*assembly.Harness{h, other} {
		go func(i int, harness *assembly.Harness) {
			hdr := header(fmt.Sprintf("answer-%d", i))
			hdr.Identity.IssuerId = fmt.Sprintf("endpoint-%d", i)
			r, e := harness.Sessions.SubmitInput(ctx, &v1.Caller{UserId: "alice", IssuerId: hdr.Identity.IssuerId}, &v1.SubmitInputCommand{Header: hdr, SessionId: id, InputKind: "ANSWER", TaskId: task.TaskId, RequestRef: question, ContentRef: task.GoalRef, ExpectedInputVersion: 1, ExpectedRequirementsVersion: 1})
			results <- result{r, e}
		}(i, harness)
	}
	wins := 0
	for range 2 {
		out := <-results
		if out.e != nil {
			t.Fatal(out.e)
		}
		if out.r.Decision == v1.Decision_DECISION_ACCEPTED {
			wins++
		} else if out.r.Error.Code != "REQUEST_INVALID" {
			t.Fatalf("wrong rejection: %v", out.r)
		}
	}
	after, _ := h.Tasks.QueryTask(ctx, caller, task.TaskId)
	s, _ := other.Sessions.QuerySession(ctx, caller, id)
	if wins != 1 || after.InputVersion != 2 || after.ControlGeneration != task.ControlGeneration+1 || after.BoundInputVersion != 1 || s.LastCommittedSeq != 2 || s.Inputs[1].TaskInputSeq != 2 {
		t.Fatalf("answer race: wins=%d task=%v session=%v", wins, after, s)
	}
}

func TestInitialFormatBootstrapIsAtomicAtThreePersistenceModes(t *testing.T) {
	for _, mode := range []sqlite.FaultMode{sqlite.CrashBeforeCommit, sqlite.CrashAfterCommit, sqlite.LoseReceipt} {
		t.Run(string(mode), func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "bootstrap.db")
			child := exec.Command(os.Args[0], "-test.run=^TestFormatBootstrapChild$")
			child.Env = append(os.Environ(), "LERNA_FORMAT_DB="+path, "LERNA_FORMAT_MODE="+string(mode))
			output, e := child.CombinedOutput()
			if mode == sqlite.LoseReceipt {
				if e != nil {
					t.Fatalf("lost receipt child: %v %s", e, output)
				}
			} else {
				var exited *exec.ExitError
				if !errors.As(e, &exited) || exited.ExitCode() != sqlite.CrashExitCode {
					t.Fatalf("crash boundary not reached: %v %s", e, output)
				}
			}
			db, e := sql.Open("sqlite3", path)
			if e != nil {
				t.Fatal(e)
			}
			var objects, appID, userVersion int
			if e = db.QueryRow("SELECT count(*) FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%'").Scan(&objects); e != nil {
				t.Fatal(e)
			}
			if e = db.QueryRow("PRAGMA application_id").Scan(&appID); e != nil {
				t.Fatal(e)
			}
			if e = db.QueryRow("PRAGMA user_version").Scan(&userVersion); e != nil {
				t.Fatal(e)
			}
			if e = db.Close(); e != nil {
				t.Fatal(e)
			}
			if mode == sqlite.CrashBeforeCommit && (objects != 0 || appID != 0 || userVersion != 0) {
				t.Fatalf("partial format survived: objects=%d appid=%d version=%d", objects, appID, userVersion)
			}
			if mode != sqlite.CrashBeforeCommit && (objects == 0 || appID != 0x4c524e41 || userVersion != 1) {
				t.Fatalf("committed format lost: objects=%d appid=%d version=%d", objects, appID, userVersion)
			}
			h, e := assembly.Open(path, "alice", "local")
			if e != nil {
				t.Fatal(e)
			}
			defer h.Close()
			settings := h.StorageSettings()
			if settings.FormatVersion != 1 || settings.ContractVersion != 1 || len(settings.FormatDigest) != 64 || settings.ImplementationProfile != "lerna-m1-v1" {
				t.Fatalf("format settings: %+v", settings)
			}
			caller, c := goal()
			if _, e = h.Sessions.SubmitGoal(context.Background(), caller, c); e != nil {
				t.Fatal(e)
			}
			if e = h.Sessions.ProcessPending(context.Background(), caller); e != nil {
				t.Fatal(e)
			}
			assertOneTask(t, h, caller, c)
		})
	}
}

