func TestLedgerMetricsRetainInProgressAndWaitingInUnfinishedDenominator(t *testing.T) {
	target := simulator.New("queryable")
	target.SetBehavior("accept-and-delay")
	target.SetQueryRetryAfter(60_000)
	entered, release := make(chan struct{}), make(chan struct{})
	defer close(release)
	f := newFixtureWithTarget(t, 200, 200, false, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == "GET" {
			close(entered)
			<-release
		}
		target.ServeHTTP(w, r)
	}))
	capability, grant := configureReconciliation(t, f)
	a, start := prepareStart(t, f)
	r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
	accepted(t, r, e)
	r, e = f.h.Ledger.RequestReconciliation(f.ctx, f.caller, reconciliationCommand(f, a, capability, grant))
	accepted(t, r, e)
	ctx, cancel := context.WithTimeout(f.ctx, 5*time.Second)
	defer cancel()
	finished := make(chan error, 1)
	go func() { finished <- f.h.Ledger.ProcessReconciliations(ctx, f.caller) }()
	select {
	case <-entered:
	case <-ctx.Done():
		t.Fatal("actual query did not reach independent target")
	}
	inProgress, e := f.h.Ledger.QueryMetrics(f.ctx, f.caller)
	if e != nil || inProgress.Reconciliation.InProgress != 1 || inProgress.Reconciliation.Active != 1 || inProgress.Reconciliation.Unfinished != 1 || inProgress.Reconciliation.Completed != 0 || inProgress.UnknownBusinessOperations != 1 || inProgress.UnknownQueryOperations != 1 {
		t.Fatalf("actual in-flight query omitted from denominator %v %v", inProgress, e)
	}
	release <- struct{}{}
	if e = <-finished; e != nil {
		t.Fatal(e)
	}
	waiting, e := f.h.Ledger.QueryMetrics(f.ctx, f.caller)
	if e != nil || waiting.Reconciliation.Total != 1 || waiting.Reconciliation.Waiting != 1 || waiting.Reconciliation.Active != 0 || waiting.Reconciliation.Completed != 0 || waiting.Reconciliation.Unfinished != 1 || waiting.Unknown.Total != 1 || waiting.UnknownBusinessOperations != 1 || waiting.Reconciliation.UnknownCovered != 1 || waiting.Reconciliation.DurationAvailability != "MISSING_ORIGINAL_UNKNOWN_AND_COMPLETION_ENDPOINTS" {
		t.Fatalf("waiting plan disappeared or became completed latency %v %v", waiting, e)
	}
	requests, effects := target.Snapshot()
	if len(requests) != 2 || requests[0].Method != "POST" || requests[1].Method != "GET" || len(effects) != 0 {
		t.Fatalf("metric observation changed actual target %v %v", requests, effects)
	}
}

func TestLedgerTakeoverFencesOldWorkerAndPreservesAttempt(t *testing.T) {
	f := newFixture(t, 100, 80, false)
	p := f.propose(t, nil)
	r, e := f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("admit"), TaskId: f.task.Name, ProposalRef: p, GrantRef: f.grant})
	accepted(t, r, e)
	a, e := f.h.Tasks.QueryAdmission(f.ctx, f.caller, r.ResultRef)
	if e != nil {
		t.Fatal(e)
	}
	if e = f.h.Tasks.ProcessHandoffs(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	old, e := f.h.LedgerWork.ExecuteJob(f.ctx, f.caller, &v1.JobCommand{Identity: ledgerHeader("old-claim").Identity, ContractVersion: 1, Action: "CLAIM", AllowedTypes: []string{"EXECUTE_OPERATION"}, Limit: 1, LeaseMs: 100, ProcessInstance: "old-worker"})
	accepted(t, old, e)
	r, e = f.h.Ledger.Prepare(f.ctx, f.caller, &v1.PrepareExecutionCommand{Header: ledgerHeader("old-prepare"), OperationId: a.OperationId, ProcessInstance: "old-worker", Claim: old.Jobs[0]})
	accepted(t, r, e)
	original := r.ResultRef
	originalExecution, e := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
	if e != nil {
		t.Fatal(e)
	}
	originalSend := originalExecution.Send.Ref
	time.Sleep(120 * time.Millisecond)
	fresh, e := f.h.LedgerWork.ExecuteJob(f.ctx, f.caller, &v1.JobCommand{Identity: ledgerHeader("fresh-claim").Identity, ContractVersion: 1, Action: "CLAIM", AllowedTypes: []string{"EXECUTE_OPERATION"}, Limit: 1, LeaseMs: 30000, ProcessInstance: "fresh-worker"})
	accepted(t, fresh, e)
	r, e = f.h.Ledger.Prepare(f.ctx, f.caller, &v1.PrepareExecutionCommand{Header: ledgerHeader("stale-prepare"), OperationId: a.OperationId, ProcessInstance: "old-worker", Claim: old.Jobs[0]})
	if e != nil || r.GetError().GetCode() != "STALE_CLAIM" {
		t.Fatalf("old worker %v %v", r, e)
	}
	r, e = f.h.Ledger.Prepare(f.ctx, f.caller, &v1.PrepareExecutionCommand{Header: ledgerHeader("fresh-prepare"), OperationId: a.OperationId, ProcessInstance: "fresh-worker", Claim: fresh.Jobs[0]})
	accepted(t, r, e)
	historical, e := f.h.Ledger.QuerySend(f.ctx, f.caller, originalSend)
	if e != nil || historical.ProcessInstance != "old-worker" || historical.ClaimEpoch != 1 {
		t.Fatalf("rewritten original send: %v %v", historical, e)
	}
	x, e := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
	if e != nil || !proto.Equal(original, x.Attempt.Ref) || x.Send.ProcessInstance != "fresh-worker" || x.Send.ClaimEpoch != 2 || f.calls.Load() != 0 {
		t.Fatalf("takeover %v %v", x, e)
	}
}

func TestLocalDurabilityConnectionSettings(t *testing.T) {
	path := filepath.Join(t.TempDir(), "local.db")
