				var calls atomic.Int64
				oracle := simulator.New("idempotent")
				target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { calls.Add(1); oracle.ServeHTTP(w, r) }))
				defer target.Close()
