				if e != nil {
					t.Fatal(e)
				}
				wantEvidence := 1
				wantOutcome := "APPLIED"
				if point == "content.observation" && mode == sqlite.CrashBeforeCommit {
					wantEvidence = 0
					wantOutcome = "UNKNOWN"
				}
				if len(op.Effect.EvidenceRefs) != wantEvidence || op.Effect.Outcome != wantOutcome || calls.Load() != 1 {
					t.Fatalf("recovery %v calls %d", op, calls.Load())
				}
			})
		}
	}
}

