	target.SetBehavior("")
	claim, err := f.h.LedgerWork.ExecuteJob(f.ctx, f.caller, &v1.JobCommand{Identity: ledgerHeader("resend-claim").Identity, ContractVersion: 1, Action: "CLAIM", AllowedTypes: []string{"EXECUTE_OPERATION"}, Limit: 1, LeaseMs: 30000, ProcessInstance: "new-worker"})
	accepted(t, claim, err)
	if len(claim.Jobs) != 1 {
		t.Fatalf("claim: %v", claim)
	}
	request := &v1.PrepareResendCommand{Header: ledgerHeader("resend"), OperationId: a.OperationId, PreviousSendRef: before.Execution.Send.Ref, Claim: claim.Jobs[0]}
	r, err = f.h.Ledger.PrepareResend(f.ctx, f.caller, request)
	accepted(t, r, err)
	decision := proto.Clone(r).(*v1.CommandReceipt)
	x, err := f.h.Ledger.QueryExecution(f.ctx, f.caller, a.OperationId)
	if err != nil || x.Send.SendSeq != 2 || !proto.Equal(x.Attempt.Ref.Name, before.Execution.Attempt.Ref.Name) || !proto.Equal(x.CallDescriptor, before.Execution.CallDescriptor) {
		t.Fatalf("new send: %v %v", x, err)
	}
	second := resendStart(t, f, a, first, x, claim.Jobs[0])
	r, err = f.h.Egress.Invoke(f.ctx, actor, second)
	accepted(t, r, err)
	again, err := f.h.Ledger.PrepareResend(f.ctx, f.caller, request)
	if err != nil || !proto.Equal(again, decision) {
		t.Fatalf("replay: %v %v", again, err)
	}
	r, err = f.h.Egress.Invoke(f.ctx, actor, second)
	accepted(t, r, err)
	requests, effects := target.Snapshot()
	if len(requests) != 2 || len(effects) != 1 || requests[0].ExternalKey != requests[1].ExternalKey || requests[0].Send == requests[1].Send {
		t.Fatalf("requests=%v effects=%v", requests, effects)
	}
	op, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if err != nil || op.Effect.Outcome != "APPLIED" || op.Lifecycle != "SETTLED" || len(op.Execution.PreviousSends) != 1 {
		t.Fatalf("settled: %v %v", op, err)
	}
	reservations, err := f.h.Budget.QueryReservations(f.ctx, f.caller, a.TaskId)
	if err != nil || len(reservations) != 2 {
		t.Fatalf("reservations: %v %v", reservations, err)
	}
	budget, err := f.h.Budget.QueryBudget(f.ctx, f.caller, a.TaskId)
	if err != nil || budget.Reserved != 60 {
		t.Fatalf("unknown fees held: %v %v", budget, err)
	}
	for _, send := range []*v1.PhysicalSend{before.Execution.Send, op.Execution.Send} {
		source, err := f.h.Budget.QueryBillingSource(f.ctx, f.caller, send.Ref)
		if err != nil || source == nil || source.Amount != nil {
			t.Fatalf("source %v %v", source, err)
		}
	}
	assertResendTrace(t, f, request, decision)
}

func TestSealedInputsAllowSupplementAndOutputCannotBeOverwritten(t *testing.T) {
	ctx := context.Background()
	h, actor, d, input := derivationFixture(t)
	extra, e := h.Content.Register(ctx, actor, original("supplement", []byte("extra")))
	if e != nil {
		t.Fatal(e)
	}
	if e = h.Content.ProcessRegistrations(ctx, actor); e != nil {
		t.Fatal(e)
	}
	read := &v1.ReadDerivationInputCommand{Header: header("capture"), DerivationRef: d.Ref, HostInstanceId: d.HostInstanceId, Generation: 1, InputRef: input}
	if _, e = h.Content.ReadDerivationInput(ctx, actor, read); e != nil {
		t.Fatal(e)
	}
	r, e := h.Content.SealDerivation(ctx, actor, &v1.SealDerivationCommand{Header: header("seal"), DerivationRef: d.Ref, HostInstanceId: d.HostInstanceId, Generation: 1, InputRefs: []*v1.Ref{input, extra.ResultRef}})
	if e != nil || r.Decision != v1.Decision_DECISION_ACCEPTED {
		t.Fatalf("supplement %v %v", r, e)
	}
	read.Header = header("sealed-read")
	read.InputRef = extra.ResultRef
	if _, e = h.Content.ReadDerivationInput(ctx, actor, read); e == nil || e.Error() != "INPUT_SET_SEALED" {
		t.Fatalf("read after seal %v", e)
	}
	c := &v1.CommitDerivationCommand{Header: header("commit"), DerivationRef: d.Ref, HostInstanceId: d.HostInstanceId, Generation: 1, Body: []byte("output")}
	r, e = h.Content.CommitDerivation(ctx, actor, c)
	if e != nil || r.Decision != v1.Decision_DECISION_ACCEPTED {
		t.Fatalf("commit %v %v", r, e)
	}
	if e = h.Content.ProcessRegistrations(ctx, actor); e != nil {
		t.Fatal(e)
	}
	output, e := h.Content.Read(ctx, actor, d.OutputRef)
	if e != nil || len(output.DerivedFrom) != 2 {
		t.Fatalf("lost supplement %v %v", output, e)
	}
	duplicate, e := h.Content.CommitDerivation(ctx, actor, c)
	if e != nil || !proto.Equal(r, duplicate) {
		t.Fatalf("repeat %v %v", duplicate, e)
	}
	c.Body = []byte("changed")
	if _, e = h.Content.CommitDerivation(ctx, actor, c); e == nil || e.Error() != "IDEMPOTENCY_CONFLICT" {
		t.Fatalf("changed same command %v", e)
	}
	c.Header = header("overwrite")
	reject, e := h.Content.CommitDerivation(ctx, actor, c)
	if e != nil || reject.Decision != v1.Decision_DECISION_REJECTED {
		t.Fatalf("overwrite %v %v", reject, e)
	}
	same, e := h.Content.Read(ctx, actor, d.OutputRef)
	if e != nil || !proto.Equal(output, same) {
		t.Fatalf("output mutated %v %v", same, e)
	}
}

