		{"parameters", false, func(o *v1.Operation) { o.Execution.CallDescriptor.ParametersRef.Revision++ }},
		{"capability", false, func(o *v1.Operation) { o.Execution.CallDescriptor.CapabilityRef.Revision++ }},
		{"key", false, func(o *v1.Operation) { o.Execution.CallDescriptor.ExternalKey += "-another" }},
		{"attempt-operation", false, func(o *v1.Operation) { o.Execution.Attempt.OperationId.LocalId += "-another" }},
		{"send-attempt", false, func(o *v1.Operation) { o.Execution.Send.AttemptId.LocalId += "-another" }},
		{"model-idempotency", true, func(o *v1.Operation) { o.Execution.Attempt.Capabilities.Idempotent = true }},
		{"model-body", true, func(o *v1.Operation) { o.Execution.CallDescriptor.BodyDigest = "another-body" }},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			target := simulator.NewBillingTarget(25)
			f := newFixtureWithTarget(t, 100, 80, false, target)
			var op *v1.Operation
			provider := simulator.NewModelProvider()
			if tc.model {
				f = modelFixtureTarget(t, provider)
				run := modelRunCommand(t, f, 30000)
				if _, e := f.h.Tasks.RunModelCall(f.ctx, f.caller, run); e != nil {
					t.Fatal(e)
				}
				call, e := f.h.Tasks.QueryModelCall(f.ctx, f.caller, run.Preparation.RequestRef, 0)
				if e != nil {
					t.Fatal(e)
				}
				admission, e := f.h.Tasks.QueryAdmission(f.ctx, f.caller, call.AdmissionRef)
				if e != nil {
					t.Fatal(e)
				}
				op, e = f.h.Ledger.QueryOperation(f.ctx, f.caller, admission.OperationId)
				if e != nil {
					t.Fatal(e)
				}
			} else {
				a, _ := prepareStart(t, f)
				var e error
				op, e = f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
				if e != nil {
					t.Fatal(e)
				}
			}
			changed := proto.Clone(op).(*v1.Operation)
			tc.mutate(changed)
			changed.Execution.CallDescriptor.Digest = ""
			changed.Execution.CallDescriptor.Digest = command.SemanticFingerprint("call-descriptor-v1", changed.Execution.CallDescriptor)
			// 故障仅替换实际历史的声明或绑定；还原这些元数据后必须逐字段等于原记录。
			restored := proto.Clone(changed).(*v1.Operation)
			restored.Execution.Attempt.Capabilities = proto.Clone(op.Execution.Attempt.Capabilities).(*v1.ExecutionCapabilities)
			restored.Execution.Attempt.OperationId = proto.Clone(op.Execution.Attempt.OperationId).(*v1.GlobalName)
			restored.Execution.Send.AttemptId = proto.Clone(op.Execution.Send.AttemptId).(*v1.GlobalName)
			restored.Execution.CallDescriptor = proto.Clone(op.Execution.CallDescriptor).(*v1.CallDescriptor)
			if !proto.Equal(restored, op) {
				t.Fatal("fault changed business facts")
			}
			wire, e := proto.Marshal(changed)
			if e != nil {
				t.Fatal(e)
			}
			if e = f.h.StorageFaultSQL("UPDATE operations SET record=X'" + hex.EncodeToString(wire) + "' WHERE user_id='u' AND domain_id='d/ledger' AND id='" + op.Ref.Name.LocalId + "'"); e != nil {
				t.Fatal(e)
			}
			goal := &v1.SubmitGoalCommand{Identity: header("binding-other-owner").Identity, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "preserve original pending owner"}
			receipt, e := f.h.Sessions.SubmitGoal(f.ctx, f.caller, goal)
			if e != nil {
				t.Fatal(e)
			}
			job, e := f.h.Durable.QueryJob(f.ctx, f.caller, receipt.JobRef.Name)
			if e != nil {
				t.Fatal(e)
			}
			budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil {
				t.Fatal(e)
			}
			candidate, openErr := assembly.Open(f.path, "u", "d")
			if candidate != nil {
				if e = candidate.Close(); e != nil {
					t.Fatal(e)
				}
			}
			if openErr == nil || openErr.Error() != "PREPARATION_UNRECOVERABLE" {
				t.Errorf("unsupported original declaration/binding must fail before recovery: %v", openErr)
			}
			after, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, op.Ref.Name)
			if e != nil || !proto.Equal(changed, after) {
				t.Fatalf("original record changed: %v %v", after, e)
			}
			q, e := f.h.Durable.QueryReceipt(f.ctx, f.caller, goal.Identity)
			if e != nil || !proto.Equal(q.Receipt, receipt) {
				t.Errorf("other owner advanced: %v %v", q, e)
			}
			j, e := f.h.Durable.QueryJob(f.ctx, f.caller, job.Ref.Name)
			if e != nil || !proto.Equal(j, job) || j.State != "READY" || j.ClaimEpoch != 0 {
				t.Errorf("other job advanced: %v %v", j, e)
			}
			b, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil || !proto.Equal(b, budget) {
				t.Errorf("budget changed: %v %v", b, e)
			}
			calls, effects := target.Target.Snapshot()
			if len(calls) != 0 || len(effects) != 0 || len(target.Bills()) != 0 || tc.model && (provider.Calls() != 1 || len(provider.Bills()) != 1) {
				t.Fatal("recovery changed actual calls/effects/fees")
			}
		})
	}
}

func TestStartupChecksOriginalTaskClosingContractsBeforeAnyOwnerRecovery(t *testing.T) {
	for _, test := range []struct{ table, metadata string }{
		{"task_closings", "unknown"}, {"task_closings", "nested"},
		{"task_closure_intents", "header-version"}, {"task_closure_intents", "nested"},
		{"task_closure_seals", "unknown"}, {"task_sealed_operations", "unknown"},
		{"execution_followups", "unknown"}, {"settlement_followups", "nested"},
		{"execution_followup_jobs", "job-version"},
	} {
		t.Run(test.table+"/"+test.metadata, func(t *testing.T) {
			target := simulator.NewBillingTarget(3)
			f := newFixtureWithTarget(t, 100, 80, false, target)
			a, start := prepareStart(t, f)
			performWithoutObservation(t, f, a, start)
			closeReceipt, err := beginNonSuccessClose(t, f, "compatibility-original-close", "FAILED", "USER_STOPPED")
			accepted(t, closeReceipt, err)
			if err = processNonSuccessClosings(f, "FAILED"); err != nil {
				t.Fatal(err)
			}
			view, err := f.h.Tasks.QueryTaskClosingView(f.ctx, f.caller, f.task.Name)
			if err != nil || view.Result.GetOutcome() != "FAILED" || len(view.ClosureIntents) != 1 || len(view.ClosureSeals) != 1 || len(view.ExecutionFollowups) != 1 || len(view.SettlementFollowups) != 1 {
				t.Fatalf("actual original closing responsibility: %v %v", view, err)
			}
			fixed, err := proto.Marshal(view.Result)
			if err != nil {
				t.Fatal(err)
			}
			opBefore, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if err != nil || opBefore.Effect.Outcome != "UNKNOWN" {
				t.Fatalf("actual original UNKNOWN: %v %v", opBefore, err)
			}
			budgetBefore, err := f.h.Budget.QueryBudget(f.ctx, f.caller, f.task.Name)
			if err != nil {
				t.Fatal(err)
			}
			var original proto.Message
			var ref *v1.Ref
			switch test.table {
			case "task_closings":
				original, ref = view.Closing, view.Closing.Ref
			case "task_closure_intents":
				original, ref = view.ClosureIntents[0], view.ClosureIntents[0].Ref
			case "task_closure_seals", "task_sealed_operations":
				original, ref = view.ClosureSeals[0], view.ClosureSeals[0].Ref
			case "execution_followups":
				original, ref = view.ExecutionFollowups[0], view.ExecutionFollowups[0].Ref
			case "settlement_followups":
				original, ref = view.SettlementFollowups[0], view.SettlementFollowups[0].Ref
			case "execution_followup_jobs":
				for _, job := range view.FollowupJobs {
					if job.JobType == "RECONCILE_UNRESOLVED_OPERATION" {
						original, ref = job, job.Ref
					}
				}
			}
			if original == nil || ref == nil {
				t.Fatal("public producer did not save the required original record")
			}
			changed := proto.Clone(original)
			metadata := changed
			if test.metadata == "nested" {
				switch record := changed.(type) {
				case *v1.TaskClosing:
					metadata = record.Ref
				case *v1.TaskClosureIntent:
					metadata = record.Command.Header
				case *v1.SettlementFollowup:
					metadata = record.ReservationRefs[0]
				}
			}
			expectedError := "UNSUPPORTED_FEATURE"
			switch test.metadata {
			case "header-version":
				changed.(*v1.TaskClosureIntent).Command.Header.ContractVersion = 2
				expectedError = "UNSUPPORTED_CONTRACT"
			case "job-version":
				changed.(*v1.Job).ContractVersion = 2
				expectedError = "UNSUPPORTED_CONTRACT"
			default:
				unknown := protowire.AppendTag(nil, 19000, protowire.VarintType)
				metadata.ProtoReflect().SetUnknown(protowire.AppendVarint(unknown, 1))
			}
			back := proto.Clone(changed)
			switch test.metadata {
			case "header-version":
				back.(*v1.TaskClosureIntent).Command.Header.ContractVersion = 1
			case "job-version":
				back.(*v1.Job).ContractVersion = 1
			case "nested":
				switch record := back.(type) {
				case *v1.TaskClosing:
					record.Ref.ProtoReflect().SetUnknown(nil)
				case *v1.TaskClosureIntent:
					record.Command.Header.ProtoReflect().SetUnknown(nil)
				case *v1.SettlementFollowup:
					record.ReservationRefs[0].ProtoReflect().SetUnknown(nil)
				}
			default:
				back.ProtoReflect().SetUnknown(nil)
			}
			if !proto.Equal(back, original) {
				t.Fatal("contract metadata fault changed business facts")
			}
			wire, err := proto.Marshal(changed)
			if err != nil {
				t.Fatal(err)
			}
			domain, id := ref.Name.AuthorityDomainId, ref.Name.LocalId
			if test.table == "task_sealed_operations" {
				domain, id = a.OperationId.AuthorityDomainId, a.OperationId.LocalId
			}
			// 只改真实原记录的兼容元数据，不插入业务责任或效果。
			if err = f.h.StorageFaultSQL("UPDATE " + test.table + " SET record=X'" + hex.EncodeToString(wire) + "' WHERE user_id='u' AND domain_id='" + domain + "' AND id='" + id + "'"); err != nil {
				t.Fatal(err)
			}
			goal := &v1.SubmitGoalCommand{Identity: header("task-closing-other-owner-pending").Identity, ContractVersion: 1, SchemaId: "lerna.v1.SubmitGoal", FingerprintVersion: 1, Goal: "preserve the original queued responsibility"}
			pending, err := f.h.Sessions.SubmitGoal(f.ctx, f.caller, goal)
			if err != nil {
				t.Fatal(err)
			}
			jobBefore, err := f.h.Durable.QueryJob(f.ctx, f.caller, pending.JobRef.Name)
			if err != nil || jobBefore.State != "READY" || jobBefore.ClaimEpoch != 0 {
				t.Fatalf("actual original queued job: %v %v", jobBefore, err)
			}
			candidate, openErr := assembly.Open(f.path, "u", "d")
			if candidate != nil {
				if err = candidate.Close(); err != nil {
					t.Fatal(err)
				}
			}
			if openErr == nil || openErr.Error() != expectedError {
				t.Errorf("startup interpreted unsupported original %s: %v", test.metadata, openErr)
			}
			afterReceipt, err := f.h.Durable.QueryReceipt(f.ctx, f.caller, goal.Identity)
			if err != nil || !proto.Equal(afterReceipt.GetReceipt(), pending) {
				t.Errorf("startup advanced another original owner: %v %v", afterReceipt, err)
			}
			jobAfter, err := f.h.Durable.QueryJob(f.ctx, f.caller, pending.JobRef.Name)
			if err != nil || !proto.Equal(jobAfter, jobBefore) || jobAfter.State != "READY" || jobAfter.ClaimEpoch != 0 {
				t.Errorf("startup claimed another original job: %v %v", jobAfter, err)
			}
			opAfter, err := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
			if err != nil || !proto.Equal(opAfter, opBefore) {
				t.Errorf("startup changed original operation: %v %v", opAfter, err)
			}
			budgetAfter, err := f.h.Budget.QueryBudget(f.ctx, f.caller, f.task.Name)
			if err != nil || !proto.Equal(budgetAfter, budgetBefore) {
				t.Errorf("startup changed original budget: %v %v", budgetAfter, err)
			}
			result, err := f.h.Tasks.QueryResult(f.ctx, f.caller, f.task.Name)
			later, marshalErr := proto.Marshal(result)
			if err != nil || marshalErr != nil || !bytes.Equal(fixed, later) {
				t.Errorf("startup rewrote fixed Result: %v %v", err, marshalErr)
			}
			closeAfter, err := f.h.Durable.QueryReceipt(f.ctx, f.caller, header("compatibility-original-close").Identity)
			if err != nil || !proto.Equal(closeAfter.GetReceipt(), closeReceipt) {
				t.Errorf("startup changed original closing receipt: %v %v", closeAfter, err)
			}
			requests, effects := target.Target.Snapshot()
			if len(requests) != 1 || requests[0].Method != "POST" || len(effects) != 1 || len(target.Bills()) != 1 {
				t.Fatal("compatibility changed independent actual target history")
			}
		})
	}
}

func TestStartupReadsOriginalAPIHistoryWithoutNativeCredentialResolution(t *testing.T) {
	for _, kind := range []string{"no-execution", "registered-missing-item"} {
		t.Run(kind, func(t *testing.T) {
			f := newFixture(t, 100, 80, false)
			descriptor := configureAPI(t, f)
			keychain := withAPIKeychain(t, f, descriptor, []byte("synthetic-api-recovery-read"))
			var admission *v1.Admission
			var start *v1.StartExecutionCommand
			if kind == "registered-missing-item" {
				admission, start = prepareStart(t, f)
			} else {
				proposal := f.propose(t, nil)
				r, e := f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("api-recovery-unprepared"), TaskId: f.task.Name, ProposalRef: proposal, GrantRef: f.grant})
				accepted(t, r, e)
				admission, e = f.h.Tasks.QueryAdmission(f.ctx, f.caller, r.ResultRef)
				if e != nil {
					t.Fatal(e)
				}
				if e = f.h.Tasks.ProcessHandoffs(f.ctx, f.caller); e != nil {
					t.Fatal(e)
				}
			}
			original, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, admission.OperationId)
			if e != nil || original == nil || (kind == "no-execution") != (original.Execution == nil) {
				t.Fatalf("original actual API frontier: %v %v", original, e)
			}
			budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil {
				t.Fatal(e)
			}
			if e = keychain.Remove(descriptor.Binding); e != nil {
				t.Fatal(e)
			}
			if e = f.h.Close(); e != nil {
				t.Fatal(e)
			}
			next, e := assembly.OpenWithOptions(f.path, "u", "d", assembly.Options{APIKeychainPath: keychain.Path()})
			if e != nil {
				t.Fatal("supported original API history refused before any credential use", e)
			}
			f.h = next
			retained, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, admission.OperationId)
			if e != nil || !proto.Equal(retained, original) || f.calls.Load() != 0 {
				t.Fatalf("qualification changed original history or sent: %v %v", retained, e)
			}
			after, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil || !proto.Equal(after, budget) {
				t.Fatalf("qualification changed original budget: %v %v", after, e)
			}
			if start != nil {
				_, e = f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
				var failure *command.Failure
				if !errors.As(e, &failure) || failure.Detail.Code != "CREDENTIAL_UNAVAILABLE" {
					t.Fatalf("missing original native item was not distinguished from compatibility: %v", e)
				}
				retained, e = f.h.Ledger.QueryOperation(f.ctx, f.caller, admission.OperationId)
				if e != nil || !proto.Equal(retained, original) || f.calls.Load() != 0 || retained.Execution.Send.Phase != "REGISTERED" {
					t.Fatalf("missing item crossed P5: %v %v", retained, e)
				}
			}
			t.Logf("actual_original=%s startup_requests=0 native_item=MISSING supported_history=RETAINED no_P5=true", kind)
		})
	}
}

func TestStartupRefusesOriginalUnsupportedFileVersionsBeforeAnyOwnerRecovery(t *testing.T) {
	for _, field := range []string{"adapter", "protocol", "declaration", "verification"} {
		t.Run(field, func(t *testing.T) {
