				t.Fatal(err)
			}
			namespace := snapshotBackupFileNamespace(t, n.root)
			candidate, openErr := assembly.OpenWithFiles(n.path, "u", "d", map[string]string{"documents": n.root})
			if candidate != nil {
				if err = candidate.Close(); err != nil {
					t.Fatal(err)
