	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, p := range view.Sources {
		if p.SourceStreamId == "d/tasks" {
			found = true
			if p.AcceptedContiguous != 0 || len(p.Gaps) == 0 || p.Gaps[0].First != 1 || p.PendingReceipts == 0 {
				t.Fatalf("gap or source pending hidden: %v", p)
			}
		}
	}
