					t.Fatal(err)
				}
				after, err := h.Trace.Query(ctx, caller, &v1.TraceQuery{TaskId: c.TaskRef.Name})
				if err != nil || !proto.Equal(after, view) {
					t.Fatal("repeated recovery changed original event/receipt/index")
				}
			})
		}
	}
}

