				t.Fatalf("missing time fabricated zero age: %v %v", metrics, e)
			}
			local, e := f.h.QueryMetrics(f.ctx, f.caller)
			if e != nil {
				t.Fatal(e)
			}
			encoded, e := protojson.Marshal(local)
			if e != nil {
