				t.Fatalf("original operation changed: %v %v", after, e)
			}
			job, e := f.h.LedgerWork.QueryJob(f.ctx, f.caller, claim.Jobs[0].Ref.Name)
			if e != nil || !proto.Equal(job, claim.Jobs[0]) {
				t.Fatalf("original claim changed: %v %v", job, e)
			}
			saved, e := f.h.Tasks.QueryAdmission(f.ctx, f.caller, a.Ref)
			if e != nil || !proto.Equal(saved, a) {
				t.Fatalf("admission changed: %v %v", saved, e)
			}
			r, e := f.h.Tasks.Admit(f.ctx, f.caller, admit)
			accepted(t, r, e)
			if !proto.Equal(r, receipt) {
				t.Fatal("original admission receipt changed")
			}
			b, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
			if e != nil || !proto.Equal(b, budget) {
				t.Fatalf("budget changed: %v %v", b, e)
			}
			calls, effects := target.Target.Snapshot()
			if len(calls) != 0 || len(effects) != 0 || len(target.Bills()) != 0 || f.calls.Load() != 0 {
				t.Fatal("unsupported backend produced an external call/effect/fee")
			}
		})
	}
}

func TestUpdatesFromSameHistoricalVersionGetDistinctVersionNumbers(t *testing.T) {
	ctx := context.Background()
	h, e := assembly.Open(filepath.Join(t.TempDir(), "versions.db"), "alice", "local")
	if e != nil {
		t.Fatal(e)
	}
	defer h.Close()
	actor := &v1.Caller{UserId: "alice", IssuerId: "host"}
	r, e := h.Content.Register(ctx, actor, original("base", []byte("base")))
	if e != nil {
		t.Fatal(e)
	}
	if e = h.Content.ProcessRegistrations(ctx, actor); e != nil {
		t.Fatal(e)
	}
	refs := []*v1.Ref{}
	for _, id := range []string{"update-one", "update-two"} {
		c := original(id, []byte(id))
		c.PreviousVersionRef = r.ResultRef
		u, e := h.Content.Register(ctx, actor, c)
		if e != nil {
			t.Fatal(e)
		}
		refs = append(refs, u.ResultRef)
	}
	if e = h.Content.ProcessRegistrations(ctx, actor); e != nil {
		t.Fatal(e)
	}
	a, e := h.Content.Read(ctx, actor, refs[0])
	if e != nil {
		t.Fatal(e)
	}
	b, e := h.Content.Read(ctx, actor, refs[1])
	if e != nil {
		t.Fatal(e)
	}
	if a.ContentId != b.ContentId || a.ContentVersion != 2 || b.ContentVersion != 3 {
		t.Fatalf("version identity collision %v %v", a, b)
	}
}

func TestWaitingDependencyRoutesOriginalInputOnceAfterRestart(t *testing.T) {
	path := filepath.Join(t.TempDir(), "dependencies.db")
	h, e := assembly.Open(path, "alice", "local")
	if e != nil {
		t.Fatal(e)
	}
	id := session(t, h)
	text := stage(t, h, "pending-text", "goal")
	original := &v1.SubmitInputCommand{Header: header("dependent-goal"), SessionId: id, InputKind: "GOAL", ContentRef: text, DependsOn: []*v1.CommandIdentity{header("prerequisite").Identity}}
	r, e := h.Sessions.SubmitInput(ctx, caller, original)
	ref := accepted(t, r, e).ResultRef
	h.Close()
	h, e = assembly.Open(path, "alice", "local")
	if e != nil {
		t.Fatal(e)
	}
	defer h.Close()
	before, _ := h.Sessions.QuerySession(ctx, caller, id)
	if len(before.TaskRefs) != 0 || before.Inputs[0].RoutingStatus != "WAITING_DEPENDENCY" {
		t.Fatal("pending goal was routed early")
	}
	r, e = h.Sessions.SubmitInput(ctx, caller, &v1.SubmitInputCommand{Header: header("prerequisite"), SessionId: id, InputKind: "RECORD", ContentRef: text})
	accepted(t, r, e)
	route := &v1.RouteInputCommand{Header: header("route"), InputRef: ref}
	r, e = h.Sessions.RouteInput(ctx, caller, route)
	first := accepted(t, r, e)
	r, e = h.Sessions.RouteInput(ctx, caller, route)
	if !proto.Equal(accepted(t, r, e), first) {
		t.Fatal("route replay changed")
	}
	after, _ := h.Sessions.QuerySession(ctx, caller, id)
	if len(after.TaskRefs) != 1 || len(after.Inputs) != 2 || after.Inputs[0].SessionSeq != 1 || after.Inputs[1].SessionSeq != 2 {
		t.Fatalf("routing changed history: %v", after)
	}
	delivery, e := h.Sessions.QueryInput(ctx, caller, ref)
	if e != nil || !proto.Equal(delivery.OriginalCommand, original) || delivery.Input.RoutingStatus != "TASK_ACCEPTED" {
		t.Fatalf("lost original route: %v %v", delivery, e)
	}
}

func TestWeakQueryPreservesDelayedWriteAndDurableSchedule(t *testing.T) {
	target := simulator.New("queryable")
	target.SetBehavior("accept-and-delay")
	f := newFixtureWithTarget(t, 200, 200, false, target)
	cap, grant := configureReconciliation(t, f)
	a, start := prepareStart(t, f)
	r, e := f.h.Egress.Invoke(f.ctx, &v1.Caller{UserId: "u", IssuerId: "egress"}, start)
	accepted(t, r, e)
	original, e := f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	requests, effects := target.Snapshot()
	if e != nil || original.Effect.Outcome != "UNKNOWN" || len(requests) != 1 || len(effects) != 0 {
		t.Fatalf("accepted is not applied: %v %v %v %v", original, e, requests, effects)
	}
	target.SetQueryRetryAfter(1000)
	c := reconciliationCommand(f, a, cap, grant)
	r, e = f.h.Ledger.RequestReconciliation(f.ctx, f.caller, c)
	accepted(t, r, e)
	duplicate := proto.Clone(c).(*v1.RequestReconciliationCommand)
	duplicate.Header = ledgerHeader("duplicate-wakeup")
	r, e = f.h.Ledger.RequestReconciliation(f.ctx, f.caller, duplicate)
	accepted(t, r, e)
	if e = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	plan, e := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || plan.State != "WAITING" || plan.CheckCount != 1 || plan.NextReconcileAtUnixMs < time.Now().Add(700*time.Millisecond).UnixMilli() {
		t.Fatalf("schedule: %v %v", plan, e)
	}
	original, e = f.h.Ledger.QueryOperation(f.ctx, f.caller, a.OperationId)
	if e != nil || original.Effect.Outcome != "UNKNOWN" || original.Effect.LateEffect != "MAY_OCCUR" {
		t.Fatalf("weak absence: %v %v", original, e)
	}
	if e = f.h.Close(); e != nil {
		t.Fatal(e)
	}
	f.h, e = assembly.Open(f.path, "u", "d")
	if e != nil {
		t.Fatal(e)
	}
	restored, e := f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || restored.CheckCount < 1 || restored.CheckCount > 2 {
		t.Fatalf("restart checks: %v %v", restored, e)
	}
	requests, effects = target.Snapshot()
	if len(requests) != 1+int(restored.CheckCount) || len(effects) != 0 {
		t.Fatalf("unexpected restart I/O: %v %v", requests, effects)
	}
	// 真实存储恢复可能跨过截止时间；只用已持久的 due 和独立目标收到时间判定是否提前。
	if restored.CheckCount == 1 {
		if restored.NextReconcileAtUnixMs != plan.NextReconcileAtUnixMs {
			t.Fatalf("schedule resampled without a query: %v", restored)
		}
	} else if requests[2].Method != "GET" || requests[2].ReceivedAtUnixNano < time.UnixMilli(plan.NextReconcileAtUnixMs).UnixNano() {
		t.Fatalf("query preceded durable deadline: %v due=%d", requests, plan.NextReconcileAtUnixMs)
	}
	beforeLateChecks := restored.CheckCount
	target.ReleasePending()
	time.Sleep(time.Until(time.UnixMilli(restored.NextReconcileAtUnixMs)) + 20*time.Millisecond)
	if e = f.h.Ledger.ProcessReconciliations(f.ctx, f.caller); e != nil {
		t.Fatal(e)
	}
	plan, e = f.h.Ledger.QueryReconciliation(f.ctx, f.caller, a.OperationId)
	if e != nil || plan.State != "COMPLETED" || plan.CheckCount != beforeLateChecks+1 {
		t.Fatalf("late proof: %v %v", plan, e)
	}
	requests, effects = target.Snapshot()
	if len(requests) != 1+int(plan.CheckCount) || requests[0].Method != "POST" || len(effects) != 1 {
		t.Fatalf("unsafe duplicate write: %v %v", requests, effects)
	}
	for _, request := range requests[1:] {
		if request.Method != "GET" {
			t.Fatal("unsafe duplicate write")
		}
	}
	view := assertReconciliationTrace(t, f, plan, "APPLIED", true)
	unknown, applied := false, false
	for _, event := range view.Events {
		if event.EventType == "RECONCILIATION_FINDING" {
			unknown = unknown || event.EffectOutcome == "UNKNOWN" && event.LateEffect == "MAY_OCCUR"
			applied = applied || event.EffectOutcome == "APPLIED" && event.LateEffect == "RULED_OUT"
		}
	}
	if !unknown || !applied {
		t.Fatal("late proof rewrote original unknown finding")
	}
}

func TestWithdrawalAndAdmissionHaveOneAtomicWinner(t *testing.T) {
	f := newFixture(t, 100, 80, true)
	p := f.propose(t, nil)
	r, e := f.h.Tasks.RequestAdmissionConfirmation(f.ctx, f.caller, &v1.RequestAdmissionConfirmationCommand{Header: header("withdraw-race"), TaskId: f.task.Name, ProposalRef: p, GrantRef: f.grant})
	accepted(t, r, e)
	pending, e := f.h.Sessions.QueryConfirmation(f.ctx, f.caller, r.ResultRef)
	if e != nil {
		t.Fatal(e)
	}
	r, e = f.h.Sessions.RespondConfirmation(f.ctx, f.caller, &v1.RespondConfirmationCommand{Header: header("approve"), ConfirmationRef: pending.Ref, BindingDigest: pending.BindingDigest, Decision: "APPROVE"})
	accepted(t, r, e)
	approved := r.ResultRef
	type result struct {
		receipt *v1.CommandReceipt
		err     error
		action  string
	}
	results := make(chan result, 2)
	start := make(chan struct{})
	go func() {
		<-start
		r, e := f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("admit"), TaskId: f.task.Name, ProposalRef: p, GrantRef: f.grant, ConfirmationRef: approved})
		results <- result{r, e, "admit"}
	}()
	go func() {
		<-start
		r, e := f.h.Sessions.WithdrawConfirmation(f.ctx, f.caller, &v1.WithdrawConfirmationCommand{Header: header("withdraw"), ConfirmationRef: approved})
		results <- result{r, e, "withdraw"}
	}()
	close(start)
	winner := ""
	count := 0
	for i := 0; i < 2; i++ {
		got := <-results
		if got.err != nil {
			t.Fatal(got.err)
		}
		if got.receipt.Decision == v1.Decision_DECISION_ACCEPTED {
			count++
			winner = got.action
		} else if got.receipt.GetError().GetCode() != "CONFIRMATION_INVALID" {
			t.Fatal(got.receipt)
		}
	}
	current, e := f.h.Sessions.QueryCurrentConfirmation(f.ctx, f.caller, pending.Ref.Name)
	expected := "WITHDRAWN"
	expectedUses := 0
	expectedReserved := int64(0)
	if winner == "admit" {
		expected = "CONSUMED"
		expectedUses = 1
		expectedReserved = 30
	}
	if e != nil || count != 1 || current.State != expected {
		t.Fatalf("winner %q count %d current %v err %v", winner, count, current, e)
	}
	uses, e := f.h.Grants.QueryUses(f.ctx, f.caller, f.task.Name)
	if e != nil || len(uses) != expectedUses {
		t.Fatalf("uses: %v %v", uses, e)
	}
	budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
	if e != nil || budget.Reserved != expectedReserved {
		t.Fatalf("budget: %v %v", budget, e)
	}
	if f.calls.Load() != 0 {
		t.Fatal("confirmation race called target")
	}
}

func TestWithdrawnConfirmationCannotConsumeAuthority(t *testing.T) {
	f := newFixture(t, 100, 80, true)
	p := f.propose(t, nil)
	goal, e := f.h.Durable.QueryReceipt(f.ctx, f.caller, header("goal").Identity)
	if e != nil {
		t.Fatal(e)
	}
	before, e := f.h.Tasks.QueryTask(f.ctx, f.caller, f.task.Name)
	if e != nil {
		t.Fatal(e)
	}
	r, e := f.h.Tasks.RequestAdmissionConfirmation(f.ctx, f.caller, &v1.RequestAdmissionConfirmationCommand{Header: header("request-confirmation"), TaskId: f.task.Name, ProposalRef: p, GrantRef: f.grant, SessionId: goal.Receipt.SessionRef.Name})
	accepted(t, r, e)
	pending, e := f.h.Sessions.QueryConfirmation(f.ctx, f.caller, r.ResultRef)
	if e != nil {
		t.Fatal(e)
	}
	r, e = f.h.Sessions.RespondConfirmation(f.ctx, f.caller, &v1.RespondConfirmationCommand{Header: header("approve"), ConfirmationRef: pending.Ref, BindingDigest: pending.BindingDigest, Decision: "APPROVE"})
	accepted(t, r, e)
	approved := r.ResultRef
	responseReplay, e := f.h.Sessions.RespondConfirmation(f.ctx, f.caller, &v1.RespondConfirmationCommand{Header: header("approve"), ConfirmationRef: pending.Ref, BindingDigest: pending.BindingDigest, Decision: "APPROVE"})
	if e != nil || !proto.Equal(responseReplay, r) {
		t.Fatalf("response replay: %v %v", responseReplay, e)
	}
	r, e = f.h.Sessions.WithdrawConfirmation(f.ctx, f.caller, &v1.WithdrawConfirmationCommand{Header: header("withdraw"), ConfirmationRef: approved})
	accepted(t, r, e)
	withdrawn := r.ResultRef
	withdrawReplay, e := f.h.Sessions.WithdrawConfirmation(f.ctx, f.caller, &v1.WithdrawConfirmationCommand{Header: header("withdraw"), ConfirmationRef: approved})
	if e != nil || !proto.Equal(withdrawReplay, r) {
		t.Fatalf("withdrawal replay: %v %v", withdrawReplay, e)
	}
	session, e := f.h.Sessions.QuerySession(f.ctx, f.caller, goal.Receipt.SessionRef.Name)
	if e != nil || len(session.Inputs) != 3 {
		t.Fatalf("duplicate events: %v %v", session, e)
	}
	for i, expected := range []*v1.Ref{approved, withdrawn} {
		event := session.Inputs[i+1]
		delivery, e := f.h.Sessions.QueryInput(f.ctx, f.caller, &v1.Ref{Name: event.InputId, Revision: 1, SchemaId: "lerna.v1.SessionInput"})
		if e != nil || delivery == nil || !proto.Equal(delivery.Input, event) || !proto.Equal(event.ConfirmationRef, expected) {
			t.Fatalf("event query: %v %v", delivery, e)
		}
	}
	after, e := f.h.Tasks.QueryTask(f.ctx, f.caller, f.task.Name)
	if e != nil || !proto.Equal(before, after) {
		t.Fatalf("confirmation changed task: %v %v", after, e)
	}
	current, e := f.h.Sessions.QueryCurrentConfirmation(f.ctx, f.caller, pending.Ref.Name)
	if e != nil || current.State != "WITHDRAWN" {
		t.Fatalf("withdrawal: %v %v", current, e)
	}
	r, e = f.h.Tasks.Admit(f.ctx, f.caller, &v1.AdmitCommand{Header: header("admit"), TaskId: f.task.Name, ProposalRef: p, GrantRef: f.grant, ConfirmationRef: approved})
	if e != nil || r.GetError().GetCode() != "CONFIRMATION_INVALID" {
		t.Fatalf("withdrawn admission: %v %v", r, e)
	}
	uses, e := f.h.Grants.QueryUses(f.ctx, f.caller, f.task.Name)
	if e != nil || len(uses) != 0 {
		t.Fatalf("partial use: %v %v", uses, e)
	}
	budget, e := f.h.Budget.QueryBudget(f.ctx, f.caller, nil)
	if e != nil || budget.Reserved != 0 {
		t.Fatalf("partial budget: %v %v", budget, e)
	}
	if f.calls.Load() != 0 {
		t.Fatal("withdrawal called target")
	}
}
